def soma_digitos_primos(n: int) -> int:
    primos = {2, 3, 5, 7}
    soma = 0
    n = abs(n)
    while n > 0:
        digito = n % 10
        if digito in primos:
            soma += digito
        n //= 10
    return soma

def mmc_lista(numeros: list) -> int:
    import math
    def mdc(a, b):
        while b:
            a, b = b, a % b
        return a
    def mmc_dois(a, b):
        return a * b // mdc(a, b)
    resultado = 1
    for num in numeros:
        resultado = mmc_dois(resultado, num)
    return resultado

