    if not matriz:
        return False
    n = len(matriz)
    for linha in matriz:
        if len(linha) != n:
            return False
    for i in range(n):
        for j in range(n):
            if i == j:
                if matriz[i][j] != 1:
                    return False
            else:
                if matriz[i][j] != 0:
                    return False
    return True

