    def min_moedas(v):
        if v in memo:
            return memo[v]
        menor = float('inf')
        for m in moedas:
            if m <= v:
                menor = min(menor, 1 + min_moedas(v - m))
        memo[v] = menor
        return menor
    return min_moedas(valor)

