    if not log_text:
        return contagem
    for linha in log_text.split('\n'):
        linha = linha.strip()
        if linha.startswith('['):
            fechado = linha.find(']')
            if fechado > 1:
                nivel = linha[1:fechado]
                if nivel in contagem:
                    contagem[nivel] += 1
    return contagem

