solution:
def parse_keyvalue(text: str) -> dict:
    result = {}
    if not text.strip():
        return result
    for token in text.split():
        if '=' in token:
            key, _, value = token.partition('=')
            result[key] = value
    return result

def parse_csv_to_lists(csv_str: str) -> list[list[str]]:
    rows = []
    current_row = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(csv_str)
    while i < n:
        c = csv_str[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and csv_str[i+1] == '"':
                    current_field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                current_field.append(c)
        else:
            if c == '"':
                in_quotes = True
            elif c == ',':
                current_row.append(''.join(current_field))
                current_field = []
            elif c == '\n':
                current_row.append(''.join(current_field))
                current_field = []
                rows.append(current_row)
                current_row = []
            else:
                current_field.append(c)
        i += 1
    if current_field or current_row:
        current_row.append(''.join(current_field))
        rows.append(current_row)
    return rows

