def count_errors_by_date(log_str: str) -> dict:
    """Conta logs de nível ERROR por data em uma string de log.
    Cada linha no formato 'YYYY-MM-DD HH:MM:SS LEVEL mensagem'.
    Retorna dicionário mapeando data (string) para número de erros.
    Exemplo: count_errors_by_date('2023-01-01 12:00:00 ERROR err1\n2023-01-01 13:00:00 INFO inf1\n2023-01-02 10:00:00 ERROR err2') -> {'2023-01-01':1, '2023-01-02':1}
    """

solution:
def count_errors_by_date(log_str: str) -> dict:
    import re
    from collections import defaultdict
    pattern = r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} ERROR'
    counts = defaultdict(int)
    for line in log_str.splitlines():
        match = re.match(pattern, line)
        if match:
            date = match.group(1)
            counts[date] += 1
    return dict(counts)

