def parse_ini_string(ini_str: str) -> dict:
    """Analisa uma string no formato INI e retorna um dicionário aninhado.
    Seções são definidas por [secao]. Comentários começam com ; ou #.
    Chaves globais (antes de qualquer seção) são colocadas em seção 'default'.
    Exemplo: parse_ini_string('[db]\nhost=localhost\n[cfg]\nport=8080') -> {'db':{'host':'localhost'}, 'cfg':{'port':'8080'}}
    """

solution:
def parse_ini_string(ini_str: str) -> dict:
    result = {}
    current_section = 'default'
    for line in ini_str.splitlines():
        line = line.strip()
        if not line or line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            continue
        if '=' in line:
            key, _, value = line.partition('=')
            key = key.strip()
            value = value.strip()
            if current_section not in result:
                result[current_section] = {}
            result[current_section][key] = value
    return result

def media_ponderada(valores: list, pesos: list) -> float:
    if not valores or not pesos or len(valores) != len(pesos):
        return 0.0
    soma = 0.0
    soma_pesos = 0.0
    for v, p in zip(valores, pesos):
        soma += v * p
        soma_pesos += p
    if soma_pesos == 0:
        return 0.0
    return round(soma / soma_pesos, 2)

def mediana_manual(numeros: list) -> float:
    if not numeros:
        return 0.0
    nums = numeros[:]
    n = len(nums)
    for i in range(n):
        for j in range(0, n - i - 1):
            if nums[j] > nums[j + 1]:
                nums[j], nums[j + 1] = nums[j + 1], nums[j]
    if n % 2 == 1:
        return float(nums[n // 2])
    else:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2.0

def moda_com_desempate(numeros: list) -> list:
