        return []
    freq = {}
    for num in numeros:
        freq[num] = freq.get(num, 0) + 1
    max_freq = max(freq.values())
    modas = [num for num, f in freq.items() if f == max_freq]
    modas.sort()
    return modas

def desvio_padrao_amostral(numeros: list) -> float:
    if len(numeros) < 2:
        return 0.0
    n = len(numeros)
    media = sum(numeros) / n
    soma_quad = sum((x - media) ** 2 for x in numeros)
    var = soma_quad / (n - 1)
    return round(var ** 0.5, 4)

