solution:
def frequencia_estreita(itens) -> dict:
    from collections import Counter
    freq = {}
    ordem = []
    vistos = {}
    for i, item in enumerate(itens):
        if item not in vistos:
            vistos[item] = i
            ordem.append(item)
    contagem = Counter(itens)
    for item in ordem:
        if contagem[item] >= 2:
            freq[item] = contagem[item]
    return freq

