def run_length_encode(s: str) -> str:
    if not s:
        return ''
    resultado = []
    cont = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            cont += 1
        else:
            resultado.append(s[i-1])
            if cont > 1:
                resultado.append(str(cont))
            cont = 1
    # último caractere
    resultado.append(s[-1])
    if cont > 1:
        resultado.append(str(cont))
    return ''.join(resultado)

def run_length_decode(s: str) -> str:
    resultado = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        num_str = ''
        while i < len(s) and s[i].isdigit():
            num_str += s[i]
            i += 1
        if num_str:
            resultado.append(char * int(num_str))
        else:
            resultado.append(char)
    return ''.join(resultado)

