def arredondar_para_baixo(n: float, casas: int = 0) -> float:
    """Arredonda um número float para baixo (em direção a -inf) com precisão de 'casas' decimais, SEM usar math.floor.
    Exemplo: arredondar_para_baixo(3.14159, 2) -> 3.14; arredondar_para_baixo(-2.7, 0) -> -3.0"""

solution:
def arredondar_para_baixo(n: float, casas: int = 0) -> float:
    fator = 10 ** casas
    if n >= 0:
        return int(n * fator) / fator
    else:
        # Para números negativos, int trunca em direção a zero, então precisamos subtrair um
        return (int(n * fator) if n * fator == int(n * fator) else int(n * fator) - 1) / fator

def soma_algarismos_base(n: int, base: int) -> int:
    if not (2 <= base <= 16):
        raise ValueError("Base deve estar entre 2 e 16")
    if n < 0:
        n = -n
    if n == 0:
        return 0
    total = 0
    while n > 0:
        digito = n % base
        # Como base <= 16, digito já é o valor numérico (0-15)
        total += digito
        n //= base
    return total

def numeros_amigaveis_ate(n: int) -> list:
    def soma_divisores_proprios(x: int) -> int:
        if x <= 1:
            return 0
        soma = 1
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                soma += i
                if i != x // i:
                    soma += x // i
        return soma

    pares = []
    for a in range(2, n + 1):
        b = soma_divisores_proprios(a)
        if b > a and b <= n and soma_divisores_proprios(b) == a:
            pares.append((a, b))
    return pares

def converte_base_fracionaria(numero: str, base_origem: int, base_destino: int, precisao: int = 5) -> str:
    def char_para_valor(c):
        if '0' <= c <= '9':
            return ord(c) - ord('0')
        else:
            return ord(c.upper()) - ord('A') + 10

    def valor_para_char(v):
        if v < 10:
            return chr(ord('0') + v)
        else:
            return chr(ord('A') + v - 10)

    # Separar parte inteira e fracionária
    if '.' in numero:
        parte_int_str, parte_frac_str = numero.split('.')
    else:
        parte_int_str, parte_frac_str = numero, ''

    # Converter parte inteira para decimal
    inteiro_decimal = 0
    for c in parte_int_str:
        inteiro_decimal = inteiro_decimal * base_origem + char_para_valor(c)

    # Converter parte fracionária para decimal
    frac_decimal = 0.0
    for i, c in enumerate(parte_frac_str):
        frac_decimal += char_para_valor(c) * (base_origem ** (-i - 1))

    # Converter parte inteira para base destino
    if inteiro_decimal == 0:
        parte_int_destino = '0'
    else:
        parte_int_destino = ''
        temp = inteiro_decimal
        while temp > 0:
            parte_int_destino = valor_para_char(temp % base_destino) + parte_int_destino
            temp //= base_destino

    # Converter parte fracionária para base destino
    parte_frac_destino = ''
    frac_temp = frac_decimal
    for _ in range(precisao):
        frac_temp *= base_destino
        digito = int(frac_temp)
        parte_frac_destino += valor_para_char(digito)
        frac_temp -= digito
        if frac_temp == 0.0:
            break

    if parte_frac_destino:
        # Remover zeros à direita?
        # A especificação pede truncar, não arredondar. Manter zeros internos mas remover zeros à direita?
        # Exemplo: 0.5 em base 10 para base 2 precisao=5 gera '0.1' (sem zeros à direita)
        # Vamos remover zeros à direita para simplificar, mas o exemplo mostra sem zeros
        parte_frac_destino = parte_frac_destino.rstrip('0')
        if parte_frac_destino:
            return parte_int_destino + '.' + parte_frac_destino
        else:
            return parte_int_destino
    else:
        return parte_int_destino

def dias_entre_datas_uteis(data_inicio: str, data_fim: str, formato: str = "%Y-%m-%d") -> int:
    from datetime import datetime, timedelta
    inicio = datetime.strptime(data_inicio, formato).date()
    fim = datetime.strptime(data_fim, formato).date()
    if inicio >= fim:
        return 0
    dias_uteis = 0
    atual = inicio
    while atual < fim:
        if atual.weekday() < 5:
            dias_uteis += 1
        atual += timedelta(days=1)
    return dias_uteis

def diferenca_em_segundos(hora_inicio: str, hora_fim: str, formato: str = "%H:%M:%S") -> int:
    from datetime import datetime
    inicio = datetime.strptime(hora_inicio, formato)
    fim = datetime.strptime(hora_fim, formato)
    if fim >= inicio:
        return int((fim - inicio).total_seconds())
    else:
        # Passou da meia-noite: considera que fim é do próximo dia
        from datetime import timedelta
        fim_ajustado = fim + timedelta(days=1)
        return int((fim_ajustado - inicio).total_seconds())

def idade_em_anos(data_nascimento: str, data_referencia: str = None, formato: str = "%Y-%m-%d") -> int:
    from datetime import datetime
    nasc = datetime.strptime(data_nascimento, formato).date()
    if data_referencia is None:
        ref = datetime.now().date()
    else:
        ref = datetime.strptime(data_referencia, formato).date()
    idade = ref.year - nasc.year
    # Verifica se o aniversário já passou este ano
    if (ref.month, ref.day) < (nasc.month, nasc.day):
        idade -= 1
    return idade

def to_snake_case(s: str) -> str:
    if not s:
        return ''
    result = []
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0 and (s[i-1].islower() or (s[i-1].isdigit() and i+1 < len(s) and s[i+1].islower())):
                result.append('_')
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)

def to_camel_case(s: str) -> str:
    if not s:
