def estatisticas_completas(numeros: list) -> dict:
    if not numeros:
        return {'media': 0.0, 'mediana': 0.0, 'moda': [], 'desvio': 0.0}
    media = sum(numeros) / len(numeros)
    ordenados = sorted(numeros)
    n = len(ordenados)
    meio = n // 2
    if n % 2 == 1:
        mediana = float(ordenados[meio])
    else:
        mediana = round((ordenados[meio-1] + ordenados[meio]) / 2, 1)
    freq = {}
    for x in numeros:
        freq[x] = freq.get(x, 0) + 1
    max_freq = max(freq.values())
    moda = sorted([k for k, v in freq.items() if v == max_freq])
    if n <= 1:
        desvio = 0.0
    else:
        var = sum((x - media) ** 2 for x in numeros) / n
        desvio = round(var ** 0.5, 2)
    return {'media': round(media, 2), 'mediana': mediana, 'moda': moda, 'desvio': desvio}

def amplitude_e_variancia(numeros: list) -> tuple:
