        return (0.0, 0.0)
    amplitude = max(numeros) - min(numeros)
    media = sum(numeros) / len(numeros)
    variancia = sum((x - media) ** 2 for x in numeros) / len(numeros)
    return (round(amplitude, 2), round(variancia, 2))

def arredondar_para_fracao(n: float, denom: int) -> int:
