def numeros_amigos_ate(limite: int) -> list:
    def soma_div(n):
        if n <= 1:
            return 0
        s = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                s += i
                if i != n // i:
                    s += n // i
        return s

    pares = []
    for a in range(2, limite + 1):
        b = soma_div(a)
        if b > a and b <= limite and soma_div(b) == a:
            pares.append((a, b))
