def busca_binaria_limites(arr: list[int], alvo: int) -> int:
    if not arr:
        return -1
    esq, dir = 0, len(arr) - 1
    while esq < dir:
        meio = (esq + dir) // 2
        if arr[meio] < alvo:
            esq = meio + 1
        else:
            dir = meio
    return esq if arr[esq] == alvo else -1

def two_pointers_palindromo_remocao(s: str) -> bool:
    def eh_palindromo(i: int, j: int) -> bool:
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return eh_palindromo(i + 1, j) or eh_palindromo(i, j - 1)
        i += 1
        j -= 1
    return True

def janela_deslizante_max_soma_k(arr: list[float], k: int) -> float | None:
    if not arr or k <= 0 or k > len(arr):
        return None
    soma = sum(arr[:k])
    max_soma = soma
    for i in range(k, len(arr)):
        soma += arr[i] - arr[i - k]
        if soma > max_soma:
            max_soma = soma
    return float(max_soma)

def busca_binaria_raiz_cubica(n: float) -> float:
    if n == 0:
        return 0.0
    sinal = 1 if n > 0 else -1
    n_abs = abs(n)
    esq, dir = 0.0, max(1.0, n_abs)
    while (dir - esq) > 1e-10:
        meio = (esq + dir) / 2
        if meio ** 3 < n_abs:
            esq = meio
        else:
            dir = meio
    return sinal * (esq + dir) / 2

def two_pointers_tres_somas_zero_sem_dup(nums: list[int]) -> list[list[int]]:
