    n = len(nums)
    resultado = []
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        esq, dir = i + 1, n - 1
        while esq < dir:
            soma = nums[i] + nums[esq] + nums[dir]
            if soma == 0:
                resultado.append([nums[i], nums[esq], nums[dir]])
                esq += 1
                dir -= 1
                while esq < dir and nums[esq] == nums[esq - 1]:
                    esq += 1
                while esq < dir and nums[dir] == nums[dir + 1]:
                    dir -= 1
            elif soma < 0:
                esq += 1
            else:
                dir -= 1
    return resultado

