def arredondar_para_par(n: float) -> int:
    # Arredonda para o inteiro mais próximo, com desempate para par
    import math
    inteiro = int(math.floor(n)) if n >= 0 else int(math.ceil(n))
    frac = n - inteiro
    if abs(frac) < 0.5:
        return inteiro
    elif abs(frac) > 0.5:
        return inteiro + (1 if n >= 0 else -1)
    else:  # exatamente 0.5
        if inteiro % 2 == 0:
            return inteiro
        else:
            return inteiro + (1 if n >= 0 else -1)

def divisores_proprios(n: int) -> list:
    if n <= 1:
        return []
    divisores = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i < n:
                divisores.append(i)
            if i != n // i and n // i < n:
                divisores.append(n // i)
    return sorted(divisores)

def eh_quadrado_perfeito(n: int) -> bool:
    if n < 0:
        return False
    i = 0
    while i * i < n:
