def elementos_frequentes_em_todos(lista_listas: list[list], min_freq: int) -> set:
    if min_freq == 0:
        uniao = set()
        for sub in lista_listas:
            uniao.update(sub)
        return uniao
    if not lista_listas or min_freq > len(lista_listas):
        return set()
    from collections import Counter
    contagem = Counter()
    for sub in lista_listas:
        # adiciona cada elemento uma vez por sublista
        for elem in set(sub):
            contagem[elem] += 1
    return {elem for elem, freq in contagem.items() if freq >= min_freq}

