    n = len(matriz)
    principal = [matriz[i][i] for i in range(n)]
    secundaria = [matriz[i][n - 1 - i] for i in range(n)]
    return (principal, secundaria)

def multiplicar_matrizes_3x3(a: list, b: list) -> list:
    if len(a) != 3 or len(b) != 3 or any(len(linha) != 3 for linha in a) or any(len(linha) != 3 for linha in b):
        return None
    resultado = [[0, 0, 0] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                resultado[i][j] += a[i][k] * b[k][j]
    return resultado

def caminho_soma_maxima(matriz: list) -> int:
    if not matriz or not matriz[0]:
        return 0
    n = len(matriz)
    m = len(matriz[0])
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = matriz[0][0]
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + matriz[0][j]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + matriz[i][0]
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = matriz[i][j] + max(dp[i-1][j], dp[i][j-1])
    return dp[n-1][m-1]

def busca_binaria_quadrada(x: float, epsilon: float = 1e-10) -> float:
    if x < 0:
        return -1.0
    if x == 0.0:
        return 0.0
    low, high = 0.0, max(1.0, x)
    while high - low > epsilon:
        mid = (low + high) / 2.0
        if mid * mid > x:
            high = mid
        else:
            low = mid
    return (low + high) / 2.0

def dois_ponteiros_subarray_maior_soma(arr: list) -> int:
