def janela_deslizante_max_sliding(arr: list, k: int) -> list:
    if not arr or k <= 0 or k > len(arr):
        return []
    from collections import deque
    dq = deque()
    resultado = []
    for i in range(len(arr)):
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        while dq and arr[dq[-1]] <= arr[i]:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            resultado.append(arr[dq[0]])
    return resultado

def maximo_subarray_div_conq(nums: list) -> int:
    def recursivo(esq, dir):
        if esq == dir:
            return nums[esq]
        meio = (esq + dir) // 2
        max_esq = recursivo(esq, meio)
        max_dir = recursivo(meio + 1, dir)
        soma_esq = float('-inf')
        soma_temp = 0
        for i in range(meio, esq - 1, -1):
            soma_temp += nums[i]
            if soma_temp > soma_esq:
                soma_esq = soma_temp
        soma_dir = float('-inf')
        soma_temp = 0
        for i in range(meio + 1, dir + 1):
            soma_temp += nums[i]
            if soma_temp > soma_dir:
                soma_dir = soma_temp
        max_cruz = soma_esq + soma_dir
        return max(max_esq, max_dir, max_cruz)
    if not nums:
        return 0
    return recursivo(0, len(nums) - 1)

def numero_deformado_recursivo(n: int) -> bool:
    def soma_quadrados(x):
        if x == 0:
            return 0
        return (x % 10) ** 2 + soma_quadrados(x // 10)
    def aux(num, visitados):
        if num == 1:
            return True
        if num in visitados:
            return False
        visitados.add(num)
        return aux(soma_quadrados(num), visitados)
    if n <= 0:
        return False
    return aux(n, set())

def decompoe_soma_memo(s: int, numeros: list) -> bool:
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def aux(restante):
        if restante == 0:
            return True
        if restante < 0:
            return False
        for num in numeros:
            if aux(restante - num):
                return True
        return False
    return aux(s)

def torre_hanoi_max_memo(n: int) -> int:
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def hanoi(k):
        if k == 0:
            return 0
        return 2 * hanoi(k-1) + 1
    return hanoi(n)

def subset_sum_memo(nums: list[int], target: int) -> bool:
    memo = {}
    def dfs(i, remaining):
        if remaining == 0:
            return True
        if i >= len(nums) or remaining < 0:
            return False
        key = (i, remaining)
        if key not in memo:
            memo[key] = dfs(i+1, remaining) or dfs(i+1, remaining - nums[i])
        return memo[key]
    return dfs(0, target)

def grid_paths_memo(m: int, n: int) -> int:
    memo = {}
    def paths(i, j):
        if i == 1 or j == 1:
            return 1
        key = (i, j)
        if key not in memo:
            memo[key] = paths(i-1, j) + paths(i, j-1)
        return memo[key]
    return paths(m, n)

def longest_palindromic_subseq(s: str) -> int:
    n = len(s)
    memo = {}
    def lps(l, r):
        if l > r:
            return 0
        if l == r:
            return 1
        key = (l, r)
        if key not in memo:
            if s[l] == s[r]:
                memo[key] = 2 + lps(l+1, r-1)
            else:
                memo[key] = max(lps(l+1, r), lps(l, r-1))
        return memo[key]
    return lps(0, n-1) if n > 0 else 0

def coeficiente_binomial_memo(n: int, k: int) -> int:
    if k > n:
        return 0
    memo = {}
    def c(n, k):
        if k == 0 or k == n:
            return 1
        key = (n, k)
        if key not in memo:
            memo[key] = c(n-1, k-1) + c(n-1, k)
        return memo[key]
    return c(n, k)

def permutacoes_unicas(s: str) -> list[str]:
    from collections import Counter
    result = []
    def backtrack(prefix, counter):
        if len(prefix) == len(s):
            result.append(prefix)
            return
        for ch in sorted(counter):
            if counter[ch] > 0:
                counter[ch] -= 1
                backtrack(prefix + ch, counter)
                counter[ch] += 1
    if s:
        backtrack('', Counter(s))
    return result

def intersecao_ordenada_sem_duplicatas(lista1: list, lista2: list) -> list:
