def contar_pares_soma_zero(lista: list) -> int:
    if len(lista) < 2:
        return 0
    from collections import Counter
    freq = Counter(lista)
    total = 0
    for num, count in freq.items():
        if num == 0:
            total += count * (count - 1) // 2
        elif num > 0 and -num in freq:
            total += count * freq[-num]
    return total

def conjunto_potencia_contagem(conjunto: set) -> int:
    if not conjunto:
        return 0
    n = len(conjunto)
    total = 0
    elementos = list(conjunto)
    for mask in range(1, 1 << n):
        soma = 0
        for i in range(n):
            if mask & (1 << i):
                soma += elementos[i]
        if soma % 2 == 0:
            total += 1
    return total

def mediana_lista(numeros: list) -> float:
