def validar_versao_semver(versao: str) -> bool:
    if not versao:
        return False
    # Separar metadados de build, se houver
    if '+' in versao:
        partes = versao.split('+', 1)
        if len(partes) != 2 or not partes[0] or not partes[1]:
            return False
        versao = partes[0]
        # Validação básica do build: não vazio, sem caracteres inválidos (apenas alfanuméricos, ponto, hífen)
        build = partes[1]
        for c in build:
