    padrao = r'^\((\d{2})\)\s(\d{4,5})-(\d{4})$'
    match = re.match(padrao, telefone)
    if not match:
        return False
    ddd = int(match.group(1))
    prefixo = match.group(2)
    sufixo = match.group(3)
    if not (11 <= ddd <= 99):
        return False
    if len(prefixo) == 5:
        # celular deve começar com 9
        if prefixo[0] != '9':
