    elif len(prefixo) == 4:
        # fixo: sem restrição do primeiro dígito, apenas 8 dígitos no total
        pass
    else:
        return False
    # total de dígitos: ddd (2) + prefixo + sufixo = 10 ou 11 dígitos sem DDD
