    # Remove hífen para facilitar
    placa_limpa = placa.replace('-', '')
    # Tentar antiga: 3 letras + 4 dígitos
    padrao_antiga = r'^([A-Z]{3})(\d{4})$'
    match_antiga = re.match(padrao_antiga, placa_limpa)
    if match_antiga:
        return {'tipo': 'antiga', 'letras': match_antiga.group(1), 'numeros': match_antiga.group(2), 'valida': True}
    # Tentar mercosul: 3 letras + 1 dígito + 1 letra + 2 dígitos
    padrao_mercosul = r'^([A-Z]{3})(\d)([A-Z])(\d{2})$'
    match_mercosul = re.match(padrao_mercosul, placa_limpa)
    if match_mercosul:
        letras = match_mercosul.group(1)
        digito1 = match_mercosul.group(2)
        letra_meio = match_mercosul.group(3)
        digito23 = match_mercosul.group(4)
        numeros = digito1 + digito23  # concatena os 3 dígitos
        return {'tipo': 'mercosul', 'letras': letras, 'numeros': numeros, 'valida': True}
    return {'tipo': 'invalida', 'valida': False}

