def parse_log_severity_summary(log_text: str) -> list[tuple[str, int]]:
    import re
    severity_map = {'INFO': 1, 'WARN': 2, 'ERROR': 3, 'DEBUG': 0, 'TRACE': 0, 'FATAL': 4}
    pattern = r'\b(?:' + '|'.join(severity_map.keys()) + r')\b'
    matches = re.findall(pattern, log_text, re.IGNORECASE)
    counts = {}
    for m in matches:
        key = m.upper()
        if severity_map.get(key, 0) > 0:  # Só considera severidades com peso > 0
            counts[key] = counts.get(key, 0) + 1
    # Ordenar: por severidade decrescente, depois alfabeticamente
    sorted_items = sorted(counts.items(), key=lambda x: (-severity_map[x[0]], x[0]))
    return sorted_items

