def saldo_minimo_para_viagem_memo(dias: list, custo_diario: int, custo_7: int, custo_30: int) -> int:
    dias = sorted(set(dias))
    if not dias:
        return 0
    dias_set = set(dias)

    @lru_cache(None)
    def dp(pos):
        if pos > 365:
            return 0
        if pos not in dias_set:
            return dp(pos + 1)
        return min(custo_diario + dp(pos + 1),
                   custo_7 + dp(pos + 7),
                   custo_30 + dp(pos + 30))
    return dp(1)

from functools import lru_cache

def maior_subsequencia_comum_memo(s1: str, s2: str) -> str:
    @lru_cache(None)
    def lcs(i, j):
        if i == len(s1) or j == len(s2):
            return ''
        if s1[i] == s2[j]:
            return s1[i] + lcs(i+1, j+1)
        else:
            op1 = lcs(i+1, j)
            op2 = lcs(i, j+1)
            if len(op1) > len(op2):
                return op1
            elif len(op1) < len(op2):
                return op2
            else:
                return min(op1, op2)
    return lcs(0, 0)

