def particiona_conjunto_recursivo(numeros: list[int]) -> bool:
    total = sum(numeros)
    if total % 2 != 0:
        return False
    alvo = total // 2
    memo = {}
    def pode_somar(i, soma_atual):
        if soma_atual == alvo:
            return True
        if i >= len(numeros) or soma_atual > alvo:
            return False
        if (i, soma_atual) in memo:
            return memo[(i, soma_atual)]
        resultado = pode_somar(i+1, soma_atual + numeros[i]) or pode_somar(i+1, soma_atual)
        memo[(i, soma_atual)] = resultado
        return resultado
    return pode_somar(0, 0)

