def parse_csv_custom(texto: str, sep: str = ',', quote: str = '"') -> list:
    if not texto:
        return []
    linhas = []
    for linha in texto.split('\n'):
        campos = []
        campo_atual = []
        em_aspas = False
        i = 0
        while i < len(linha):
            ch = linha[i]
            if ch == quote:
                if em_aspas:
                    if i+1 < len(linha) and linha[i+1] == quote:
                        campo_atual.append(quote)
                        i += 1
                    else:
                        em_aspas = False
                else:
                    em_aspas = True
            elif ch == sep and not em_aspas:
                campos.append(''.join(campo_atual))
                campo_atual = []
            else:
                campo_atual.append(ch)
            i += 1
        if em_aspas:
            return []
        campos.append(''.join(campo_atual))
        linhas.append(campos)
    return linhas

