solution:
def parse_keyvalue_duplicatas(texto: str, par_sep: str = '&', kv_sep: str = '=') -> dict:
    if not texto:
        return {}
    resultado = {}
    for par in texto.split(par_sep):
        if kv_sep not in par:
            continue
        chave, _, valor = par.partition(kv_sep)
        if chave in resultado:
            resultado[chave].append(valor)
        else:
            resultado[chave] = [valor]
    return resultado

def parse_log_timestamp_range(log: str) -> str:
    if not log:
        return 'vazio'
    from datetime import datetime
    timestamps = []
    for linha in log.split('\n'):
        partes = linha.strip().split(' ', 2)
        if len(partes) < 2:
            continue
        try:
            ts = datetime.strptime(partes[0] + ' ' + partes[1], '%Y-%m-%d %H:%M:%S')
            timestamps.append(ts)
        except ValueError:
            continue
    if not timestamps:
        return 'vazio'
    inicio = min(timestamps)
    fim = max(timestamps)
    return f'{inicio.strftime("%Y-%m-%d %H:%M:%S")} -> {fim.strftime("%Y-%m-%d %H:%M:%S")}'

def parse_csv_para_dict(texto: str, sep: str = ',') -> list:
    if not texto:
        return []
    linhas = texto.split('\n')
    cabecalho = linhas[0].split(sep)
    resultado = []
    for linha in linhas[1:]:
        if not linha.strip():
            continue
        campos = linha.split(sep)
        if len(campos) != len(cabecalho):
            continue
        d = {}
        for i, chave in enumerate(cabecalho):
            d[chave] = campos[i]
        resultado.append(d)
    return resultado

