solution:
def parse_keyvalue_aninhado(texto: str) -> dict:
    if not texto:
        return {}
    resultado = {}
    for par in texto.split('&'):
        if '=' not in par:
            continue
        chave, valor = par.split('=', 1)
        partes = chave.split('.')
        atual = resultado
        for i, parte in enumerate(partes):
