                    atual[parte] = {}
                atual = atual[parte]
    return resultado

def maximo_subsequencia_crescente(nums: list[int]) -> int:
    from functools import lru_cache
    n = len(nums)
    if n == 0:
        return 0

    @lru_cache(None)
    def dfs(i: int) -> int:
        melhor = 1
        for j in range(i + 1, n):
            if nums[j] > nums[i]:
                melhor = max(melhor, 1 + dfs(j))
        return melhor

    return max(dfs(i) for i in range(n))

def combinacoes_memo_simples(n: int, k: int) -> int:
    from functools import lru_cache
    @lru_cache(None)
    def c(n: int, k: int) -> int:
        if k == 0 or k == n:
            return 1
        return c(n - 1, k - 1) + c(n - 1, k)
    return c(n, k)

def soma_minima_triangulo(triangulo: list[list[int]]) -> int:
    from functools import lru_cache
    n = len(triangulo)
    @lru_cache(None)
    def dfs(linha: int, col: int) -> int:
        if linha == n - 1:
            return triangulo[linha][col]
        esquerda = dfs(linha + 1, col)
        direita = dfs(linha + 1, col + 1)
        return triangulo[linha][col] + min(esquerda, direita)
    return dfs(0, 0)

def caminho_grid_obstaculos(grid: list[list[int]]) -> int:
    from functools import lru_cache
    if not grid or grid[0][0] == 1:
        return 0
    m, n = len(grid), len(grid[0])
    @lru_cache(None)
    def dfs(i: int, j: int) -> int:
        if i == m - 1 and j == n - 1:
            return 1
        if i >= m or j >= n or grid[i][j] == 1:
            return 0
        return dfs(i + 1, j) + dfs(i, j + 1)
    return dfs(0, 0)

def numero_subconjuntos_soma(nums: list[int], alvo: int) -> int:
    from functools import lru_cache
    n = len(nums)
    @lru_cache(None)
    def dfs(i: int, soma: int) -> int:
        if i == n:
            return 1 if soma == 0 else 0
        incluir = dfs(i + 1, soma - nums[i])
        excluir = dfs(i + 1, soma)
        return incluir + excluir
    return dfs(0, alvo)

def decompor_soma_minima_quadrados(n: int) -> int:
    from functools import lru_cache
    @lru_cache(None)
    def dfs(restante: int) -> int:
        if restante == 0:
            return 0
        menor = float('inf')
        i = 1
        while i * i <= restante:
            menor = min(menor, 1 + dfs(restante - i * i))
            i += 1
        return menor
    return dfs(n)

def diferenca_dias_uteis(data1: str, data2: str) -> int:
    from datetime import datetime, timedelta
    d1 = datetime.strptime(data1, '%d/%m/%Y')
    d2 = datetime.strptime(data2, '%d/%m/%Y')
    if d1 == d2:
        return 0
    if d2 < d1:
        return -diferenca_dias_uteis(data2, data1)
    dias_uteis = 0
    delta = timedelta(days=1)
    corrente = d1 + delta
    while corrente <= d2:
        if corrente.weekday() < 5:
            dias_uteis += 1
        corrente += delta
    return dias_uteis

def formata_data_extenso(data: str) -> str:
    from datetime import datetime
    d = datetime.strptime(data, '%d/%m/%Y')
    meses = {1:'janeiro', 2:'fevereiro', 3:'março', 4:'abril', 5:'maio', 6:'junho',
             7:'julho', 8:'agosto', 9:'setembro', 10:'outubro', 11:'novembro', 12:'dezembro'}
    return f"{d.day} de {meses[d.month]} de {d.year}"

def proximo_dia_util(data: str) -> str:
    from datetime import datetime, timedelta
    d = datetime.strptime(data, '%d/%m/%Y')
    while d.weekday() >= 5:
        d += timedelta(days=1)
    return d.strftime('%d/%m/%Y')

from functools import lru_cache

def count_ways_climb(steps: list[int], target: int) -> int:
    @lru_cache(maxsize=None)
    def helper(t: int) -> int:
        if t == 0:
            return 1
        if t < 0:
            return 0
        total = 0
        for step in steps:
            total += helper(t - step)
        return total
    return helper(target)

from functools import lru_cache

def lcs_length(str1: str, str2: str) -> int:
    @lru_cache(maxsize=None)
    def helper(i: int, j: int) -> int:
        if i == len(str1) or j == len(str2):
            return 0
        if str1[i] == str2[j]:
            return 1 + helper(i+1, j+1)
        else:
            return max(helper(i+1, j), helper(i, j+1))
    return helper(0, 0)

from functools import lru_cache

def edit_distance(s1: str, s2: str) -> int:
    @lru_cache(maxsize=None)
    def helper(i: int, j: int) -> int:
        if i == len(s1):
            return len(s2) - j
        if j == len(s2):
            return len(s1) - i
        if s1[i] == s2[j]:
            return helper(i+1, j+1)
        else:
            return 1 + min(helper(i+1, j), helper(i, j+1), helper(i+1, j+1))
    return helper(0, 0)

from functools import lru_cache

def subset_sum_count(nums: list[int], target: int) -> int:
    @lru_cache(maxsize=None)
    def helper(i: int, t: int) -> int:
        if t == 0:
            return 1
        if i == len(nums):
            return 0
        count = helper(i+1, t)
        if nums[i] <= t:
            count += helper(i+1, t - nums[i])
        return count
    return helper(0, target)

def mesclar_dicionarios_por_chave(lista_dicts: list[dict]) -> dict:
    resultado = {}
    for d in lista_dicts:
        id_ = d['id']
        if id_ not in resultado:
            resultado[id_] = {}
        for k, v in d.items():
            if k == 'id':
                continue
            if k in resultado[id_]:
                resultado[id_][k] += v
            else:
                resultado[id_][k] = v
    # Garantir que chaves faltantes apareçam com 0
    # Determinar todas as chaves possíveis
    todas_chaves = set()
    for d in lista_dicts:
        for k in d:
            if k != 'id':
                todas_chaves.add(k)
    for id_ in resultado:
        for c in todas_chaves:
            if c not in resultado[id_]:
                resultado[id_][c] = 0
    return resultado

def transpor_matriz_irregular(matriz: list[list]) -> list[list]:
    if not matriz:
        return []
    max_cols = max(len(linha) for linha in matriz) if matriz else 0
    if max_cols == 0:
        return []
    transposta = []
    for col in range(max_cols):
        nova_linha = []
        for linha in matriz:
            if col < len(linha):
                nova_linha.append(linha[col])
            else:
                nova_linha.append(None)
        transposta.append(nova_linha)
    return transposta

def maior_subsequencia_crescente_memo(nums: list[int]) -> int:
    if not nums:
        return 0
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i):
        melhor = 1
        for j in range(i + 1, len(nums)):
            if nums[j] > nums[i]:
                melhor = max(melhor, 1 + dfs(j))
        return melhor
    return max(dfs(i) for i in range(len(nums)))

def minimo_saltos_recursivo(nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return 0
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def solve(pos):
        if pos >= n - 1:
            return 0
        if nums[pos] == 0:
            return float('inf')
        melhor = float('inf')
        for passo in range(1, nums[pos] + 1):
            sub = solve(pos + passo)
            if sub != float('inf'):
                melhor = min(melhor, 1 + sub)
        return melhor
    resultado = solve(0)
    return -1 if resultado == float('inf') else resultado

def numero_formas_moedas(valor: int, moedas: list[int]) -> int:
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def contagem(val, idx):
        if val == 0:
            return 1
        if val < 0 or idx >= len(moedas):
            return 0
        incluir = contagem(val - moedas[idx], idx)
        excluir = contagem(val, idx + 1)
        return incluir + excluir
    return contagem(valor, 0)

def diferenca_minima_particao(nums: list[int]) -> int:
    total = sum(nums)
    n = len(nums)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(idx, soma_atual):
        if idx == n:
            return abs(total - 2 * soma_atual)
        incluir = dfs(idx + 1, soma_atual + nums[idx])
        excluir = dfs(idx + 1, soma_atual)
        return min(incluir, excluir)
    return dfs(0, 0) if nums else 0

def combinacoes_parenteses(n: int) -> list[str]:
    resultado = []
    def backtrack(aberto, fechado, atual):
        if len(atual) == 2 * n:
            resultado.append(''.join(atual))
            return
        if aberto < n:
            backtrack(aberto + 1, fechado, atual + ['('])
        if fechado < aberto:
            backtrack(aberto, fechado + 1, atual + [')'])
    backtrack(0, 0, [])
    return resultado

def soma_subconjuntos_recursivo(nums: list[int], alvo: int) -> bool:
    n = len(nums)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(idx, soma_parcial):
        if soma_parcial == alvo and idx > 0:
            return True
        if idx == n:
            return False
        incluir = dfs(idx + 1, soma_parcial + nums[idx])
        excluir = dfs(idx + 1, soma_parcial)
        return incluir or excluir
    return dfs(0, 0) if nums else (alvo == 0)

def find_all_substring_indices(s: str, sub: str, overlapping: bool = True) -> list[int]:
    if not sub or not s:
        return []
    indices = []
    step = 1 if overlapping else len(sub)
    start = 0
    while True:
        pos = s.find(sub, start)
        if pos == -1:
            break
        indices.append(pos)
        start = pos + step
    return indices

def format_cnpj(raw: str) -> str | None:
    import re
    digits = re.sub(r'\D', '', raw)
    if len(digits) != 14:
        return None
    return f'{digits[:2]}.{digits[2:5]}.{digits[5:8]}/{digits[8:12]}-{digits[12:]}'

def contar_palavras_unicas(texto: str) -> int:
    import re
    # remove pontuação, substitui por espaço
    limpo = re.sub(r'[.,!?;:"\'()\-\[\]{}]', ' ', texto)
    palavras = limpo.lower().split()
    return len(set(palavras))

def contar_ocorrencias_aninhadas(lista_alvo: list, elemento_busca) -> int:
    contador = 0
    for item in lista_alvo:
        if isinstance(item, list):
            contador += item.count(elemento_busca)
        # Não conta se o item não for lista
    return contador

def frequencia_ordenada_por_ocorrencia(sequencia: list) -> list:
    from collections import Counter
    contagem = Counter(sequencia)
    # Ordem de primeira aparição: usar índice da primeira ocorrência
    primeira_aparicao = {}
    for idx, elem in enumerate(sequencia):
        if elem not in primeira_aparicao:
            primeira_aparicao[elem] = idx
    itens = list(contagem.items())
    itens.sort(key=lambda x: (-x[1], primeira_aparicao[x[0]]))
    return itens

def intersecao_multiconjunto(lista1: list, lista2: list) -> list:
    from collections import Counter
    freq2 = Counter(lista2)
    resultado = []
    contagem_usada = {}
    for elem in lista1:
        if elem in freq2:
            usados = contagem_usada.get(elem, 0)
            if usados < freq2[elem]:
                resultado.append(elem)
                contagem_usada[elem] = usados + 1
    return resultado

def interseccao_listas_com_limpeza(*listas: list) -> list:
    if len(listas) < 2:
        return []
    def limpar(lista):
        return {x for x in lista if isinstance(x, int) and x >= 0}
    conjuntos = [limpar(lst) for lst in listas]
    intersec = conjuntos[0]
    for s in conjuntos[1:]:
        intersec = intersec & s
    return sorted(intersec)

def duplicatas_por_faixa(lista_numeros: list) -> int:
    from collections import Counter
    filtrado = [x for x in lista_numeros if isinstance(x, int) and 0 <= x <= 100]
    contagem = Counter(filtrado)
    return sum(1 for v in contagem.values() if v > 1)

def transpor_matriz_retangular(M: list) -> list:
    if not M:
        return []
    linhas = len(M)
    colunas = len(M[0]) if linhas > 0 else 0
    return [[M[i][j] for i in range(linhas)] for j in range(colunas)]

def rotacionar_matriz_90_anti_horario(M: list) -> list:
    if not M:
        return []
    n = len(M)
    return [[M[j][n-1-i] for j in range(n)] for i in range(n)]

def achatar_aninhado(lista: list) -> list:
    resultado = []
    for item in lista:
        if isinstance(item, list):
            resultado.extend(achatar_aninhado(item))
        elif isinstance(item, (str, int, float)):
            resultado.append(item)
    return resultado

def subtrair_matrizes_com_erro(A: list, B: list) -> list:
    if len(A) != len(B):
        return None
    resultado = []
    for i in range(len(A)):
        if len(A[i]) != len(B[i]):
            return None
        linha = []
        for j in range(len(A[i])):
            linha.append(A[i][j] - B[i][j])
        resultado.append(linha)
    return resultado

def ordenar_por_ultimo_nome(lista: list[dict]) -> list[dict]:
    def chave(dicionario):
        nome = dicionario['nome']
        partes = nome.split(' ')
        return (partes[1], partes[0])
    return sorted(lista, key=chave)

def filtrar_por_media_turma(registros: list[dict]) -> list[dict]:
    if not registros:
        return []
    media = sum(r['nota'] for r in registros) / len(registros)
    return [r for r in registros if r['nota'] >= media]

def agrupar_por_inicial(lista: list[str]) -> dict:
    resultado = {}
    for s in lista:
        if s == '':
            continue
        primeiro = s[0]
        if primeiro.isalpha():
            chave = primeiro.upper()
        else:
            chave = primeiro
        if chave not in resultado:
            resultado[chave] = []
        resultado[chave].append(s)
    return resultado

def busca_binaria_first_greater(arr: list[int], target: int) -> int:
    lo, hi = 0, len(arr) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] > target:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

def janela_deslizante_max_sum_k(arr: list[int], k: int) -> int:
    n = len(arr)
    if n < k or k <= 0:
        return 0
    window_sum = sum(arr[:k])
    max_sum = window_sum
    for i in range(k, n):
        window_sum += arr[i] - arr[i - k]
        if window_sum > max_sum:
            max_sum = window_sum
    return max_sum

def dois_ponteiros_palindromo_permutacao(s: str) -> bool:
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    odd_count = 0
    for count in freq.values():
        if count % 2 != 0:
            odd_count += 1
    return odd_count <= 1

def busca_binaria_raiz_quadrada_inteira(x: int) -> int:
    if x < 0:
        return -1
    lo, hi = 0, x
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= x:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def first_occurrence_binary(arr: list[int], target: int) -> int:
    if not arr:
        return -1
    lo, hi = 0, len(arr) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            result = mid
            hi = mid - 1
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

def max_sum_subarray_fixed(arr: list[int], k: int) -> int | None:
    if k <= 0 or k > len(arr):
        return None
    window_sum = sum(arr[:k])
    max_sum = window_sum
    for i in range(k, len(arr)):
        window_sum += arr[i] - arr[i - k]
        if window_sum > max_sum:
            max_sum = window_sum
    return max_sum

def integer_sqrt_floor(n: int) -> int | None:
    if n < 0:
        return None
    if n == 0:
        return 0
    lo, hi = 1, n
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return mid
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

def length_longest_substring_no_repeat(s: str) -> int:
    char_index = {}
    left = 0
    max_len = 0
    for right, ch in enumerate(s):
        if ch in char_index and char_index[ch] >= left:
            left = char_index[ch] + 1
        char_index[ch] = right
        max_len = max(max_len, right - left + 1)
    return max_len

def dois_ponteiros_tres_somas(arr: list[int]) -> list[tuple[int, int, int]]:
    arr.sort()
    resultado = []
    n = len(arr)
    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        esq, dir = i + 1, n - 1
        while esq < dir:
            soma = arr[i] + arr[esq] + arr[dir]
            if soma == 0:
                resultado.append((arr[i], arr[esq], arr[dir]))
                while esq < dir and arr[esq] == arr[esq + 1]:
                    esq += 1
                while esq < dir and arr[dir] == arr[dir - 1]:
                    dir -= 1
                esq += 1
                dir -= 1
            elif soma < 0:
                esq += 1
            else:
                dir -= 1
    return resultado

def busca_binaria_limiar(arr: list[float], limiar: float) -> int:
    esq, dir = 0, len(arr)
    while esq < dir:
        meio = (esq + dir) // 2
        if arr[meio] >= limiar:
            dir = meio
        else:
            esq = meio + 1
    return esq

def janela_deslizante_max_media_subarray(arr: list[float], k: int) -> float:
    if k > len(arr) or k <= 0:
        return -1.0
    soma_atual = sum(arr[:k])
    max_soma = soma_atual
    for i in range(k, len(arr)):
        soma_atual = soma_atual - arr[i - k] + arr[i]
        if soma_atual > max_soma:
            max_soma = soma_atual
    return max_soma / k

def extrair_dominios_unicos(emails: list) -> list:
