            dominios.add(dominio.lower())
    return sorted(dominios)

def contar_maiusculas_minusculas_digitos(texto: str) -> tuple:
    maiusculas = sum(1 for c in texto if c.isupper())
    minusculas = sum(1 for c in texto if c.islower())
    digitos = sum(1 for c in texto if c.isdigit())
    return (maiusculas, minusculas, digitos)

def is_happy_number(n: int) -> bool:
    if n <= 0:
        return False
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d)**2 for d in str(n))
    return n == 1

def count_divisors(n: int) -> int:
    if n == 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
        i += 1
    return count

def lcm(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    def gcd(x, y):
        return x if y == 0 else gcd(y, x % y)
    return abs(a * b) // gcd(a, b)

def moda_com_empates(lista: list) -> list:
    if not lista:
        return []
    freq = {}
    for valor in lista:
        freq[valor] = freq.get(valor, 0) + 1
    max_freq = max(freq.values())
    modas = [chave for chave, f in freq.items() if f == max_freq]
    return sorted(modas)

def desvio_medio_absoluto(lista: list) -> float:
    if not lista:
        return None
    if len(lista) == 1:
        return 0.0
    ordenada = sorted(lista)
    n = len(ordenada)
    meio = n // 2
    if n % 2 == 1:
        mediana = ordenada[meio]
    else:
        mediana = (ordenada[meio - 1] + ordenada[meio]) / 2.0
    soma = sum(abs(x - mediana) for x in lista)
    return soma / n

