def agrupa_por_frequencia_decrescente(lista: list) -> list:
    from collections import Counter
    if not lista:
        return []
    freq = Counter(lista)
    # agrupar por frequência
    grupos = {}
    for elem, count in freq.items():
        grupos.setdefault(count, []).append(elem)
    # ordenar frequências decrescente
    from operator import itemgetter
    resultado = []
    for count in sorted(grupos.keys(), reverse=True):
        grupo = sorted(grupos[count])
        for elem in grupo:
            resultado.append([elem] * count)
    # Isso daria lista de listas separadas, mas o esperado é uma única lista de sublistas
    # Corrigindo: queremos uma sublista por elemento? O exemplo sugere sublista por elemento.
    # Vou refazer: para cada elemento único, criar [elem]*freq. Depois agrupar por frequência.
    resultado = []
    for count in sorted(set(freq.values()), reverse=True):
        elems = sorted([elem for elem, c in freq.items() if c == count])
        for elem in elems:
            resultado.append([elem] * count)
    return resultado

def somar_matrizes_mesmas_dimensoes(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
