def janela_deslizante_maior_media(nums: list, k: int, limite: float) -> list:
    if k <= 0 or k > len(nums):
        return []
    resultado = []
    soma = sum(nums[:k])
    if soma / k <= limite:
        resultado.append(soma / k)
    for i in range(k, len(nums)):
        soma += nums[i] - nums[i - k]
        if soma / k <= limite:
            resultado.append(soma / k)
    return resultado

from functools import lru_cache

def can_partition_equal_sum(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2 != 0:
        return False
    target = total // 2
    @lru_cache(maxsize=None)
    def dfs(idx: int, acum: int) -> bool:
        if acum == target:
            return True
        if idx >= len(nums) or acum > target:
            return False
        return dfs(idx+1, acum + nums[idx]) or dfs(idx+1, acum)
    return dfs(0, 0)

from functools import lru_cache

def cut_rod_max_revenue(prices: list[int], length: int) -> int:
    @lru_cache(maxsize=None)
    def dfs(n: int) -> int:
        if n == 0:
            return 0
        best = -float('inf')
        for i in range(1, min(n, len(prices)) + 1):
            best = max(best, prices[i-1] + dfs(n - i))
        return best
    return dfs(length)

from functools import lru_cache

def edit_distance_recursive(s: str, t: str) -> int:
    @lru_cache(maxsize=None)
    def dfs(i: int, j: int) -> int:
        if i == len(s):
            return len(t) - j
        if j == len(t):
            return len(s) - i
        if s[i] == t[j]:
            return dfs(i+1, j+1)
        insert = dfs(i, j+1)
        delete = dfs(i+1, j)
        replace = dfs(i+1, j+1)
        return 1 + min(insert, delete, replace)
    return dfs(0, 0)

