def primos_intervalo_com_soma(inicio: int, fim: int) -> list:
    def eh_primo(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    def soma_digitos(n):
        soma = 0
        while n > 0:
            soma += n % 10
            n //= 10
        return soma
    resultado = []
    for num in range(inicio, fim + 1):
        if eh_primo(num) and eh_primo(soma_digitos(num)):
            resultado.append(num)
    return resultado

