    for read_idx in range(len(arr)):
        if arr[read_idx] != val:
            arr[write_idx] = arr[read_idx]
            write_idx += 1
    # Ajusta o tamanho da lista (considerando que o resto não importa)
    # Como a função deve retornar o resultado, podemos truncar
    return arr[:write_idx]

def media_lista(numeros: list) -> float:
