def estatisticas_descritivas(numeros: list) -> dict:
    if not numeros:
        return {'media': 0.0, 'mediana': 0.0, 'moda': [], 'desvio': 0.0}
    media = sum(numeros) / len(numeros)
    ordenados = sorted(numeros)
    n = len(ordenados)
    meio = n // 2
    if n % 2 == 1:
        mediana = float(ordenados[meio])
    else:
        mediana = (ordenados[meio - 1] + ordenados[meio]) / 2.0
    frequencia = {}
    for num in numeros:
        frequencia[num] = frequencia.get(num, 0) + 1
    max_freq = max(frequencia.values())
    moda = sorted([num for num, freq in frequencia.items() if freq == max_freq])
    if len(numeros) < 2:
        desvio = 0.0
    else:
        variancia = sum((x - media) ** 2 for x in numeros) / (len(numeros) - 1)
        desvio = round(variancia ** 0.5, 4)
    return {'media': float(media), 'mediana': mediana, 'moda': moda, 'desvio': desvio}

def amplitude_lista(numeros: list) -> float:
