    return float(max(numeros) - min(numeros))

def text_to_rows(csv_string: str) -> list[list[str]]:
    lines = csv_string.split('\n')
    result = []
    for line in lines:
        if line.strip() == '':
            continue
        fields = line.split(',')
        stripped_fields = [field.strip() for field in fields]
        result.append(stripped_fields)
    return result

def csv_to_dict(csv_string: str) -> dict[str, str]:
    lines = csv_string.split('\n')
    result = {}
    for line in lines:
        if line.strip() == '':
            continue
        fields = line.split(',')
        if len(fields) < 2:
            continue
        key = fields[0].strip()
        value = fields[1].strip()
        result[key] = value
    return result

def parse_nested_csv(csv_string: str) -> dict[str, list[str]]:
    lines = csv_string.split('\n')
    if not lines:
        return {}
    header = lines[0].strip().split(',')
    if header != ['id', 'items']:
        return {}
    result = {}
    for line in lines[1:]:
        if line.strip() == '':
            continue
        fields = line.split(',')
        if len(fields) != 2:
            continue
        id_val = fields[0].strip()
        items_str = fields[1].strip()
        if not id_val or not items_str:
            continue
        seen_in_row = set()
        for item in items_str.split(';'):
            item = item.strip()
            if not item or item in seen_in_row:
                continue
            seen_in_row.add(item)
            if item not in result:
                result[item] = []
            result[item].append(id_val)
    return {k: result[k] for k in sorted(result)}

def parse_csv_with_quotes(csv_string: str) -> list[list[str]]:
    csv_string = csv_string.replace('\r\n', '\n')
    rows = []
    current_row = []
    current_field = ''
    in_quotes = False
    quoted = False
    line_has_content = False
    i = 0
    while i < len(csv_string):
        ch = csv_string[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < len(csv_string) and csv_string[i+1] == '"':
                    current_field += '"'
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                current_field += ch
                i += 1
                line_has_content = True
        else:
            if ch == ',':
                if not quoted:
                    current_field = current_field.strip()
                current_row.append(current_field)
                current_field = ''
                quoted = False
                line_has_content = True
                i += 1
            elif ch == '\n':
                if not quoted:
                    current_field = current_field.strip()
                current_row.append(current_field)
                if line_has_content and current_row:
                    rows.append(current_row)
                current_row = []
                current_field = ''
                quoted = False
                in_quotes = False
                line_has_content = False
                i += 1
            elif ch == '"':
                if current_field.strip() == '':
                    current_field = ''
                    quoted = True
                    in_quotes = True
                    i += 1
                else:
                    current_field += ch
                    i += 1
                    line_has_content = True
            else:
                current_field += ch
                i += 1
                if not ch.isspace():
                    line_has_content = True
    if line_has_content or current_row:
        if not quoted:
            current_field = current_field.strip()
        current_row.append(current_field)
        if line_has_content and current_row:
            rows.append(current_row)
    return rows

def group_csv_by_column(csv_string: str, group_col: str, agg_col: str) -> dict[str, list[str]]:
    lines = csv_string.split('\n')
    if not lines:
        return {}
    header = [h.strip() for h in lines[0].split(',')]
    if group_col not in header or agg_col not in header:
        return {}
    group_idx = header.index(group_col)
    agg_idx = header.index(agg_col)
    result = {}
    for line in lines[1:]:
        if line.strip() == '':
            continue
        fields = [f.strip() for f in line.split(',')]
        if len(fields) <= max(group_idx, agg_idx):
            continue
        group_val = fields[group_idx]
        agg_val = fields[agg_idx]
        if group_val == '' or agg_val == '':
            continue
        if group_val not in result:
            result[group_val] = []
        result[group_val].append(agg_val)
    return result

def rotate_90_clockwise(matrix: list[list]) -> list[list]:
    if not matrix or not matrix[0]:
        return []
    rows, cols = len(matrix), len(matrix[0])
    return [[matrix[rows - 1 - r][c] for r in range(rows)] for c in range(cols)]

def matrix_diagonal_sum(matrix: list[list[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0
    n = len(matrix)
    total = 0
    for i in range(n):
        total += matrix[i][i]
        total += matrix[i][n-1-i]
    if n % 2 == 1:
        mid = n // 2
        total -= matrix[mid][mid]
    return total

def flip_horizontal(matrix: list[list]) -> list[list]:
    if not matrix:
        return []
    return [row[::-1] for row in matrix]

def flip_vertical(matrix: list[list]) -> list[list]:
    if not matrix:
        return []
    return matrix[::-1]

def is_square_matrix(matrix: list[list]) -> bool:
    if not matrix:
        return True
    rows = len(matrix)
    if any(len(row) != rows for row in matrix):
        return False
    return True

def add_matrices_with_padding(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
    if not A and not B:
        return []
    rows = max(len(A), len(B))
    cols = 0
    for mat in (A, B):
        if mat:
            cols = max(cols, max(len(row) for row in mat))
    result = [[0]*cols for _ in range(rows)]
    for i in range(len(A)):
        for j in range(len(A[i])):
            result[i][j] += A[i][j]
    for i in range(len(B)):
        for j in range(len(B[i])):
            result[i][j] += B[i][j]
    return result

def contagem_primos_intervalo(a: int, b: int) -> int:
    if a > b:
        return 0
    def eh_primo(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True
    return sum(1 for x in range(max(a, 2), b+1) if eh_primo(x))

def arredonda_para_baixo(numero: float, casas: int) -> float:
    fator = 10 ** casas
    if numero >= 0:
        return int(numero * fator) / fator
    else:
        return -((-numero * fator) // 1 + 1) / fator

def soma_numeros_base_k(a: str, b: str, base: int) -> str:
    def para_decimal(s):
        negativo = s.startswith('-')
        if negativo:
            s = s[1:]
        valor = 0
        for c in s:
            valor = valor * base + int(c)
        return -valor if negativo else valor
    def de_decimal(n):
        if n == 0:
            return '0'
        negativo = n < 0
        if negativo:
            n = -n
        digitos = []
        while n > 0:
            digitos.append(str(n % base))
            n //= base
        res = ''.join(reversed(digitos))
        return '-' + res if negativo else res
    return de_decimal(para_decimal(a) + para_decimal(b))

