def estatisticas_basicas(dados: list) -> dict:
    if not dados:
        return {'media': 0.0, 'mediana': 0.0, 'moda': [], 'desvio': 0.0}
    n = len(dados)
    media = sum(dados) / n
    dados_ord = sorted(dados)
    meio = n // 2
    if n % 2 == 1:
        mediana = float(dados_ord[meio])
    else:
        mediana = (dados_ord[meio - 1] + dados_ord[meio]) / 2.0
    freq = {}
    for x in dados:
        freq[x] = freq.get(x, 0) + 1
    max_freq = max(freq.values())
    moda = [x for x, f in freq.items() if f == max_freq]
    moda.sort()
    if n < 2:
        desvio = 0.0
    else:
        var = sum((x - media) ** 2 for x in dados) / (n - 1)
        desvio = var ** 0.5
    return {'media': media, 'mediana': mediana, 'moda': moda, 'desvio': desvio}

