def format_bytes(bytes_val: int, decimal_places: int = 2) -> str:
    if bytes_val == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    unit_index = 0
    value = float(bytes_val)
    while value >= 1024 and unit_index < len(units) - 1:
        value /= 1024
        unit_index += 1
    # round_half_up
    factor = 10 ** decimal_places
    rounded = int(value * factor + 0.5) / factor
    if decimal_places == 0:
        return f'{int(rounded)} {units[unit_index]}'
    else:
        return f'{rounded:.{decimal_places}f} {units[unit_index]}'

def parse_bytes(byte_str: str) -> int:
    if not byte_str:
        return -1
    parts = byte_str.strip().split()
    if len(parts) != 2:
        return -1
    try:
        value = float(parts[0])
    except ValueError:
        return -1
    unit = parts[1].upper()
    units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3, 'TB': 1024**4}
    if unit not in units:
        return -1
    return int(value * units[unit])

