def caminho_minimo_triangulo(triangulo: list[list[int]]) -> int:
    @lru_cache(maxsize=None)
    def dfs(linha: int, col: int) -> int:
        if linha == len(triangulo) - 1:
            return triangulo[linha][col]
        esquerda = dfs(linha + 1, col)
        direita = dfs(linha + 1, col + 1)
        return triangulo[linha][col] + min(esquerda, direita)
    return dfs(0, 0)

from functools import lru_cache

def conta_moedas_minimo(moedas: list[int], valor: int) -> int:
    @lru_cache(maxsize=None)
    def dfs(restante: int) -> int:
        if restante == 0:
            return 0
        if restante < 0:
            return float('inf')
        melhor = float('inf')
        for m in moedas:
            if m <= restante:
                res = dfs(restante - m)
                if res != float('inf'):
                    melhor = min(melhor, 1 + res)
        return melhor
    resultado = dfs(valor)
    return -1 if resultado == float('inf') else resultado

from functools import lru_cache

def decorrencias_palindromo(s: str) -> int:
    if not s:
        return 0
    n = len(s)
    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> int:
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 1 + dp(i+1, j) + dp(i, j-1)
        else:
            return dp(i+1, j) + dp(i, j-1) - dp(i+1, j-1)
    return dp(0, n-1)

