def subsequencia_comum_maxima_memo(s1: str, s2: str) -> str:
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def lcs(i, j):
        if i == len(s1) or j == len(s2):
            return ''
        if s1[i] == s2[j]:
            return s1[i] + lcs(i+1, j+1)
        else:
            a = lcs(i+1, j)
            b = lcs(i, j+1)
