def labirinto_recursivo(matriz: list, inicio: tuple, fim: tuple) -> bool:
    n = len(matriz)
    if n == 0:
        return False
    m = len(matriz[0])
    if m == 0:
        return False
    visitados = set()
    def dfs(x, y):
        if (x, y) == fim:
            return True
        if not (0 <= x < n and 0 <= y < m):
            return False
        if matriz[x][y] == 1 or (x, y) in visitados:
            return False
        visitados.add((x, y))
        if dfs(x+1, y) or dfs(x-1, y) or dfs(x, y+1) or dfs(x, y-1):
            return True
        visitados.discard((x, y))
        return False
    return dfs(inicio[0], inicio[1])

def subconjuntos_soma_memo(numeros: list, alvo: int) -> list:
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def helper(idx, soma):
        if soma == 0:
            return [[]]
        if idx >= len(numeros) or soma < 0:
            return []
        # Não pega o elemento
        res = helper(idx+1, soma)
        # Pega o elemento
        sub = helper(idx+1, soma - numeros[idx])
        for s in sub:
            res.append([numeros[idx]] + s)
        return res
    # Ordenar e remover duplicatas (se houver)
    resultados = set()
    for comb in helper(0, alvo):
        resultados.add(tuple(sorted(comb)))
    return sorted([list(t) for t in resultados])

def fibonacci_otimizado(n: int, memo: dict = None) -> int:
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n < 0:
        raise ValueError('n deve ser >= 0')
    if n <= 1:
        return n
    memo[n] = fibonacci_otimizado(n-1, memo) + fibonacci_otimizado(n-2, memo)
    return memo[n]

def eh_primo_mersenne(n: int) -> bool:
    """Verifica se n é um número primo de Mersenne, ou seja, se n é primo e pode ser escrito como 2^p - 1, onde p também é primo.
    Retorna False para n <= 1.
    Exemplo: eh_primo_mersenne(7) -> True (pois 7 = 2^3 - 1 e 3 é primo).
    """
    if n <= 1:
        return False
    def primo(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True
    if not primo(n):
        return False
    p = 0
    while (1 << p) - 1 < n:
        p += 1
    if (1 << p) - 1 == n and primo(p):
        return True
    return False

def divisivel_por_todos_ate(n: int, maximo: int) -> bool:
    """Verifica se o inteiro positivo n é divisível por todos os números inteiros de 1 a maximo inclusive.
    Se n <= 0 ou maximo <= 0, retorna False.
    Exemplo: divisivel_por_todos_ate(12, 4) -> True (12 é divisível por 1,2,3,4).
    """
    if n <= 0 or maximo <= 0:
        return False
    for i in range(1, maximo + 1):
        if n % i != 0:
            return False
    return True

def raiz_quadrada_inteira_binaria(n: int) -> int:
    """Calcula a raiz quadrada inteira de n (truncada para baixo) usando busca binária, sem usar math.sqrt ou **.
    Para n < 0, retorna -1.
    Exemplo: raiz_quadrada_inteira_binaria(10) -> 3, raiz_quadrada_inteira_binaria(16) -> 4.
    """
    if n < 0:
        return -1
    if n == 0:
        return 0
    esq, dir = 1, n
    while esq <= dir:
        meio = (esq + dir) // 2
        quadrado = meio * meio
        if quadrado == n:
            return meio
        elif quadrado < n:
            esq = meio + 1
        else:
            dir = meio - 1
    return dir

def max_subarray_sum_recursive(nums: list) -> int:
