    memo = {}
    def dp(i):
        if i == 0:
            return nums[0]
        if i in memo:
            return memo[i]
        memo[i] = max(nums[i], dp(i-1) + nums[i])
        return memo[i]
    return max(dp(i) for i in range(len(nums)))

def contar_caminhos_grid(m: int, n: int) -> int:
