        return ""
    if len(palavras) == 1:
        return palavras[0]
    def prefixo_entre(p1, p2):
        i = 0
        while i < len(p1) and i < len(p2) and p1[i] == p2[i]:
            i += 1
        return p1[:i]
    def aux(lista):
        if len(lista) == 1:
            return lista[0]
        meio = len(lista) // 2
        esq = aux(lista[:meio])
        dir = aux(lista[meio:])
        return prefixo_entre(esq, dir)
    return aux(palavras)

def coin_change_min_moedas(moedas: list, valor: int) -> int:
    memo = {}
    def dp(v):
        if v < 0:
            return float('inf')
        if v == 0:
            return 0
        if v in memo:
            return memo[v]
        melhor = float('inf')
        for m in moedas:
            melhor = min(melhor, 1 + dp(v - m))
        memo[v] = melhor
        return melhor
    res = dp(valor)
    return -1 if res == float('inf') else res

def partition_equal_subset_sum(nums: list) -> bool:
    total = sum(nums)
    if total % 2 != 0:
        return False
    alvo = total // 2
    if alvo == 0:
        return True
    memo = {}
    def dp(i, soma_atual):
        if soma_atual == alvo:
            return True
        if i >= len(nums) or soma_atual > alvo:
            return False
        if (i, soma_atual) in memo:
            return memo[(i, soma_atual)]
        incluir = dp(i+1, soma_atual + nums[i])
        excluir = dp(i+1, soma_atual)
        memo[(i, soma_atual)] = incluir or excluir
        return memo[(i, soma_atual)]
    return dp(0, 0)

