    for linha in A:
        if len(linha) != n:
            return []
    if linha_i < 0 or linha_f < 0 or col_i < 0 or col_f < 0:
        return []
    if linha_i >= m or linha_f >= m or col_i >= n or col_f >= n:
        return []
    if linha_i > linha_f or col_i > col_f:
