    return []

def max_sum_distinct_subarray(arr: list[int], k: int) -> int:
    if len(arr) < k:
        return -1
    window_sum = 0
    freq = {}
    max_sum = -1
    for i in range(len(arr)):
        window_sum += arr[i]
        freq[arr[i]] = freq.get(arr[i], 0) + 1
        if i >= k:
            window_sum -= arr[i - k]
            freq[arr[i - k]] -= 1
            if freq[arr[i - k]] == 0:
                del freq[arr[i - k]]
        if i >= k - 1:
            if len(freq) == k:
                max_sum = max(max_sum, window_sum)
    return max_sum

