        prox_mes = datetime.date(ano + 1, 1, 1)
    else:
        prox_mes = datetime.date(ano, mes + 1, 1)
    ultimo_dia = prox_mes - datetime.timedelta(days=1)
    while ultimo_dia.weekday() >= 5:
        ultimo_dia -= datetime.timedelta(days=1)
    return ultimo_dia.day

