def parse_key_value_log(log_line: str) -> dict[str, str]:
    result = {}
    i = 0
    n = len(log_line)
    while i < n:
        if log_line[i] == ' ':
            i += 1
            continue
        # Find key
        j = i
        while j < n and log_line[j] != '=':
            j += 1
        if j == n:
            break
        key = log_line[i:j]
        i = j + 1  # skip '='
        if i >= n:
            result[key] = ''
            break
        # Check for quoted value
        if log_line[i] == '"':
            i += 1
            j = i
            while j < n and log_line[j] != '"':
                j += 1
            value = log_line[i:j]
            i = j + 1 if j < n else j
        else:
            j = i
            while j < n and log_line[j] != ' ':
                j += 1
            value = log_line[i:j]
            i = j
        result[key] = value
    return result

