        while lo <= hi:
            mid = (lo+hi)//2
            if arr[mid] < target:
                lo = mid+1
            else:
                hi = mid-1
        return lo
    def last_occurrence(arr, target):
        lo, hi = 0, len(arr)-1
        while lo <= hi:
            mid = (lo+hi)//2
            if arr[mid] <= target:
                lo = mid+1
            else:
                hi = mid-1
        return hi
