def sequencia_morse_recursiva(n: int) -> str:
    if n < 0:
        return ''
    def construir(k):
        if k == 0:
            return '0'
        anterior = construir(k - 1)
        complemento = ''.join('1' if c == '0' else '0' for c in anterior)
        return anterior + complemento
    resultado = construir(n)
    return resultado[:n+1] if n < len(resultado) else resultado

def combinacoes_aninhadas_recursivas(lista: list, k: int) -> list:
    resultado = []
    def backtrack(inicio, atual):
        if len(atual) == k:
            resultado.append(atual[:])
            return
        if len(atual) + (len(lista) - inicio) < k:
            return
        for i in range(inicio, len(lista)):
            atual.append(lista[i])
            backtrack(i + 1, atual)
            atual.pop()
    if k > 0 and k <= len(lista):
        backtrack(0, [])
    return resultado

def numero_expressoes_validas(digitos: str, alvo: int) -> int:
    if not digitos:
        return 0
    memo = {}
    def dfs(idx, soma_atual):
        if idx == len(digitos):
            return 1 if soma_atual == alvo else 0
        chave = (idx, soma_atual)
        if chave in memo:
            return memo[chave]
        digito = int(digitos[idx])
        # Primeiro dígito: inicia a soma
        if idx == 0:
            memo[chave] = dfs(idx + 1, digito)
        else:
            memo[chave] = dfs(idx + 1, soma_atual + digito) + dfs(idx + 1, soma_atual - digito)
        return memo[chave]
    return dfs(0, 0)

def triangulo_pascal_recursivo(linha: int) -> list:
    if linha < 0:
        return []
    memo = {}
    def combinacao(n, k):
        if k == 0 or k == n:
            return 1
        if (n, k) in memo:
            return memo[(n, k)]
        memo[(n, k)] = combinacao(n-1, k-1) + combinacao(n-1, k)
        return memo[(n, k)]
    return [combinacao(linha, k) for k in range(linha + 1)]

