def extrair_dados_placa_antiga(placa: str) -> dict:
    """Extrai os componentes de uma placa brasileira no formato antigo (ex: ABC-1234).
    Retorna um dicionário com 'letras' e 'numeros' (string com 4 dígitos).
    Aceita com ou sem hífen. Retorna dict vazio se inválido.
    Exemplo: extrair_dados_placa_antiga('ABC-1234') -> {'letras': 'ABC', 'numeros': '1234'}
    """
    if not placa:
        return {}
    # Remover hífen
    placa_limpa = placa.replace('-', '')
    # Validar: 3 letras maiúsculas + 4 dígitos
    if len(placa_limpa) != 7:
        return {}
    letras = placa_limpa[:3]
    numeros = placa_limpa[3:]
    if not (letras.isalpha() and letras.isupper() and len(letras) == 3):
        return {}
    if not (numeros.isdigit() and len(numeros) == 4):
        return {}
    return {'letras': letras, 'numeros': numeros}

def trimmed_mean(values: list, percentage: float) -> float:
    if not values:
        raise ValueError("Lista vazia")
    n = len(values)
    k = int(n * percentage)
    if k < 0:
        k = 0
    if k * 2 >= n:
        return 0.0  # ou raise? Mas definimos retornar 0.0 para evitar erro
    sorted_vals = sorted(values)
    trimmed = sorted_vals[k:n-k]
    return sum(trimmed) / len(trimmed)

def five_number_summary(values: list) -> tuple:
    if not values:
        return (None, None, None, None, None)
    sorted_vals = sorted(values)
    n = len(sorted_vals)
    def median(sublist):
        m = len(sublist)
        if m % 2 == 0:
            return (sublist[m // 2 - 1] + sublist[m // 2]) / 2.0
        else:
            return sublist[m // 2]
    min_val = sorted_vals[0]
    max_val = sorted_vals[-1]
    med = median(sorted_vals)
    if n % 2 == 0:
        lower_half = sorted_vals[:n // 2]
        upper_half = sorted_vals[n // 2:]
    else:
        lower_half = sorted_vals[:n // 2 + 1]
        upper_half = sorted_vals[n // 2:]
    q1 = median(lower_half)
    q3 = median(upper_half)
    return (min_val, q1, med, q3, max_val)

