def maior_subsequencia_crescente_com_memo(nums: list, i: int = 0, anterior: int = None, memo: dict = None) -> int:
    if not nums:
        return 0
    if memo is None:
        memo = {}
    key = (i, anterior)
    if key in memo:
        return memo[key]
    if i == len(nums):
        return 0
    excluir = maior_subsequencia_crescente_com_memo(nums, i+1, anterior, memo)
    incluir = 0
    if anterior is None or nums[i] > anterior:
        incluir = 1 + maior_subsequencia_crescente_com_memo(nums, i+1, nums[i], memo)
    memo[key] = max(excluir, incluir)
    return memo[key]

def numero_caminhos_matriz(m: int, n: int, memo: dict = None) -> int:
    if m <= 0 or n <= 0:
        return 0
    if m == 1 and n == 1:
        return 1
    if memo is None:
        memo = {}
    if (m, n) in memo:
        return memo[(m, n)]
    memo[(m, n)] = numero_caminhos_matriz(m-1, n, memo) + numero_caminhos_matriz(m, n-1, memo)
    return memo[(m, n)]

def edit_distance_recursivo(s1: str, s2: str, i: int = 0, j: int = 0, memo: dict = None) -> int:
    if memo is None:
        memo = {}
    key = (i, j)
    if key in memo:
        return memo[key]
    if i == len(s1):
        return len(s2) - j
    if j == len(s2):
        return len(s1) - i
    if s1[i] == s2[j]:
        memo[key] = edit_distance_recursivo(s1, s2, i+1, j+1, memo)
    else:
        ins = edit_distance_recursivo(s1, s2, i, j+1, memo)
        rem = edit_distance_recursivo(s1, s2, i+1, j, memo)
        sub = edit_distance_recursivo(s1, s2, i+1, j+1, memo)
        memo[key] = 1 + min(ins, rem, sub)
    return memo[key]

def minimo_moedas_troco_recursivo(moedas: list, valor: int, memo: dict = None) -> int:
    if memo is None:
        memo = {}
    if valor in memo:
        return memo[valor]
    if valor == 0:
        return 0
    if valor < 0:
        return -1
    min_moedas = float('inf')
    for moeda in moedas:
        sub = minimo_moedas_troco_recursivo(moedas, valor - moeda, memo)
        if sub != -1:
            min_moedas = min(min_moedas, 1 + sub)
    memo[valor] = min_moedas if min_moedas != float('inf') else -1
    return memo[valor]

