    horas = segundos // 3600
    segundos %= 3600
    minutos = segundos // 60
    segundos %= 60
    partes = []
    if dias:
        partes.append(f'{dias} dia{"s" if dias != 1 else ""}')
    if horas:
        partes.append(f'{horas} hora{"s" if horas != 1 else ""}')
    if minutos:
