def parse_csv_rows(text: str, delimiter: str = ',') -> list[list[str]]:
    if not text:
        return []
    rows = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        fields = []
        current = ''
        in_quotes = False
        i = 0
        while i < len(line):
            ch = line[i]
            if ch == '"' and not in_quotes:
                in_quotes = True
            elif ch == '"' and in_quotes:
                if i+1 < len(line) and line[i+1] == '"':
                    current += '"'
                    i += 1
                else:
