        return result
    for line in text.split('\n'):
        line = line.strip() if trim else line
        if not line:
            continue
        if separator in line:
            parts = line.split(separator, 1)
            key = parts[0].strip() if trim else parts[0]
            value = parts[1].strip() if trim else parts[1]
