        line = line.strip()
        if not line:
            continue
        if line.startswith('['):
            end = line.find(']')
            if end != -1:
                level = line[1:end]
                if level in levels:
                    result[level] = result.get(level, 0) + 1
    return result

def parse_ini_section(text: str, section: str) -> dict[str, str]:
