from datetime import date, timedelta

def calculate_age_in_years(birth_date: date, reference_date: date) -> int:
    if reference_date < birth_date:
        return 0
    age = reference_date.year - birth_date.year
    if birth_date.month == 2 and birth_date.day == 29:
        leap = (reference_date.year % 4 == 0 and reference_date.year % 100 != 0) or (reference_date.year % 400 == 0)
        anniversary = date(reference_date.year, 2, 29 if leap else 28)
    else:
        anniversary = date(reference_date.year, birth_date.month, birth_date.day)
    if (reference_date.month, reference_date.day) < (anniversary.month, anniversary.day):
        age -= 1
    return age

from datetime import date, timedelta

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        return 28
    if month in (4, 6, 9, 11):
        return 30
    return 31

def add_months_to_date(d: date, months: int) -> date:
    total_months = (d.year * 12 + d.month - 1) + months
    new_year = total_months // 12
    new_month = total_months % 12 + 1
    new_day = min(d.day, _days_in_month(new_year, new_month))
    return date(new_year, new_month, new_day)

