from datetime import date, timedelta

def list_mondays_between(start: date, end: date) -> list:
    if start > end:
        return []
    first_monday = start + timedelta(days=(0 - start.weekday()) % 7)
    if first_monday > end:
        return []
    result = []
    current = first_monday
    while current <= end:
        result.append(current)
        current += timedelta(weeks=1)
    return result

from functools import lru_cache

def contar_troco(amount: int, coins: list[int]) -> int:
    coins = tuple(sorted(coins))
    @lru_cache(maxsize=None)
    def count(i: int, rest: int) -> int:
        if rest == 0:
            return 1
        if i == len(coins) or rest < 0:
            return 0
        # pular moeda atual ou usar (ilimitado)
        return count(i+1, rest) + count(i, rest - coins[i])
    return count(0, amount)

from functools import lru_cache

def custo_minimo_subir_escada(cost: list[int]) -> int:
    n = len(cost)
    @lru_cache(maxsize=None)
    def dp(i: int) -> int:
        if i < 0:
            return 0
        if i == 0 or i == 1:
            return cost[i]
        return cost[i] + min(dp(i-1), dp(i-2))
    if n == 1:
        return dp(0)
    return min(dp(n-1), dp(n-2))

