            return 1 + lcs(i-1, j-1)
        else:
            return max(lcs(i-1, j), lcs(i, j-1))
    return lcs(len(text1)-1, len(text2)-1)

from functools import lru_cache

def mochila_01(capacidade: int, pesos: list[int], valores: list[int]) -> int:
