        if i == n or cap_restante == 0:
            return 0
        if pesos[i] > cap_restante:
            return dfs(i+1, cap_restante)
        return max(dfs(i+1, cap_restante),
                   valores[i] + dfs(i+1, cap_restante - pesos[i]))
    return dfs(0, capacidade)

