def janela_deslizante_maior_substring_k_distintos(s: str, k: int) -> str:
    if k <= 0 or not s:
        return ""
    from collections import defaultdict
    freq = defaultdict(int)
    esq = 0
    maior_inicio, maior_tam = 0, 0
    for dir, char in enumerate(s):
        freq[char] += 1
        while len(freq) > k:
            freq[s[esq]] -= 1
            if freq[s[esq]] == 0:
                del freq[s[esq]]
            esq += 1
        if dir - esq + 1 > maior_tam:
            maior_tam = dir - esq + 1
            maior_inicio = esq
    return s[maior_inicio:maior_inicio + maior_tam]

def busca_binaria_pico_montanha(arr: list[int]) -> int:
