    resultado = []
    n = len(arr)
    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        esq, dir = i + 1, n - 1
        while esq < dir:
            soma = arr[i] + arr[esq] + arr[dir]
            if soma == 0:
                resultado.append((arr[i], arr[esq], arr[dir]))
                while esq < dir and arr[esq] == arr[esq + 1]:
                    esq += 1
                while esq < dir and arr[dir] == arr[dir - 1]:
