    esq = 0
    soma_atual = 0
    min_len = float('inf')
    for dir in range(len(arr)):
        soma_atual += arr[dir]
        while soma_atual >= s:
            min_len = min(min_len, dir - esq + 1)
            soma_atual -= arr[esq]
            esq += 1
    return min_len if min_len != float('inf') else 0

def subconjuntos_soma_k(nums: list[int], k: int) -> int:
