    @lru_cache(maxsize=None)
    def dfs(i: int, soma: int) -> int:
        if soma == k:
            return 1
        if i == len(nums) or soma > k:
            return 0
        return dfs(i + 1, soma + nums[i]) + dfs(i + 1, soma)
