def maior_substring_sem_repetir_recursiva(s: str) -> int:
    from functools import lru_cache
    n = len(s)
    @lru_cache(maxsize=None)
    def lss(i: int, usados: frozenset) -> int:
        if i == n:
            return 0
        char = s[i]
        if char in usados:
            return 0
        novo_usados = usados | {char}
        return 1 + lss(i + 1, novo_usados)
    max_len = 0
    for inicio in range(n):
        max_len = max(max_len, lss(inicio, frozenset()))
    return max_len

def combinacoes_moedas_troco(moedas: list[int], valor: int) -> int:
