def three_sum(nums: list) -> list:
    nums.sort()
    result = []
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        target = -nums[i]
        left, right = i + 1, n - 1
        while left < right:
            total = nums[left] + nums[right]
            if total == target:
                result.append((nums[i], nums[left], nums[right]))
                left += 1
                right -= 1
                while left < right and nums[left] == nums[left - 1]:
                    left += 1
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1
            elif total < target:
                left += 1
            else:
                right -= 1
    return result

def mediana_arredondada(lista: list, casas: int = 0) -> float:
    if not lista:
        return 0.0
    sorted_list = sorted(lista)
    n = len(sorted_list)
    if n % 2 == 1:
        med = sorted_list[n // 2]
    else:
        med = (sorted_list[n // 2 - 1] + sorted_list[n // 2]) / 2
    # arredondamento bancário
    fator = 10 ** casas
    valor = med * fator
    inteiro = int(valor)
    frac = valor - inteiro
    if abs(frac - 0.5) < 1e-9:
        if inteiro % 2 == 0:
            return inteiro / fator
        else:
            return (inteiro + 1) / fator
    else:
        return round(med, casas)

def moda_multipla(lista: list) -> list:
