def soma_dos_n_primos(n: int) -> int:
    def eh_primo(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    soma = 0
    count = 0
    num = 2
    while count < n:
        if eh_primo(num):
            soma += num
            count += 1
        num += 1 if num == 2 else 2
    return soma

def numero_em_base(numero: int, base: int) -> str:
    if base < 2 or base > 16:
        raise ValueError("Base deve estar entre 2 e 16")
    if numero == 0:
        return '0'
    digitos = '0123456789ABCDEF'
    resultado = []
    n = abs(numero)
    while n > 0:
        resultado.append(digitos[n % base])
        n //= base
    return ''.join(reversed(resultado))

def menor_divisivel_por_todos(limite: int) -> int:
