def conjunto_potencia_filtrado(conjunto: set, min_tamanho: int, max_tamanho: int) -> set:
    if min_tamanho > max_tamanho or min_tamanho < 0:
        return set()
    lista = list(conjunto)
    n = len(lista)
    resultado = set()
    for mascara in range(1 << n):
        sub = []
        for i in range(n):
            if mascara & (1 << i):
                sub.append(lista[i])
        if min_tamanho <= len(sub) <= max_tamanho:
            resultado.add(frozenset(sub))
    return resultado

def find_longest_palindromic_substring(s: str) -> str:
    if not s:
        return ''
    start, max_len = 0, 1
    def expand(l, r):
        nonlocal start, max_len
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if r - l + 1 > max_len:
                max_len = r - l + 1
                start = l
            l -= 1
            r += 1
    for i in range(len(s)):
        expand(i, i)
        expand(i, i+1)
    return s[start:start+max_len]

