def mediana_personalizada(numeros: list, ordem_decrescente: bool = False) -> float | None:
    if not numeros:
        return None
    lst = numeros[:]
    # insertion sort manual
    for i in range(1, len(lst)):
        chave = lst[i]
        j = i - 1
        if ordem_decrescente:
            while j >= 0 and lst[j] < chave:
                lst[j + 1] = lst[j]
                j -= 1
        else:
            while j >= 0 and lst[j] > chave:
                lst[j + 1] = lst[j]
                j -= 1
        lst[j + 1] = chave
    n = len(lst)
    if n % 2 == 1:
        return float(lst[n // 2])
    else:
        return (lst[n // 2 - 1] + lst[n // 2]) / 2.0

