def sliding_window_max_average(nums: list, k: int) -> float:
    window_sum = sum(nums[:k])
    max_sum = window_sum
    for i in range(k, len(nums)):
        window_sum += nums[i] - nums[i - k]
        if window_sum > max_sum:
            max_sum = window_sum
    return round(max_sum / k, 2)

def find_pair_absolute_difference(arr: list, target: int) -> bool:
    if len(arr) < 2:
        return False
    left, right = 0, 1
    while right < len(arr):
        diff = arr[right] - arr[left]
        if diff == target:
            return True
        elif diff < target:
            right += 1
        else:
            left += 1
            if left == right:
                right += 1
    return False

def binary_search_first_last(nums: list, target: int) -> list:
    def busca(primeira):
        left, right = 0, len(nums) - 1
        idx = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                idx = mid
                if primeira:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return idx
    return [busca(True), busca(False)]

