def arredondar_banco(valor: float, casas: int) -> float:
    fator = 10 ** casas
    # Multiplica e ajusta para evitar erros de ponto flutuante
    valor_shift = valor * fator
    parte_inteira = int(valor_shift)
    fracao = valor_shift - parte_inteira
    if abs(fracao - 0.5) < 1e-9:
        if parte_inteira % 2 == 0:
            resultado = parte_inteira / fator
        else:
            resultado = (parte_inteira + 1) / fator
    else:
        resultado = round(valor_shift, 0) / fator  # use round para outros casos
