def parse_csv_calcula_media(texto_csv: str, coluna_nota: str = 'nota', coluna_nome: str = 'nome') -> list[tuple[str, float]]:
    if not texto_csv:
        return []
    linhas = texto_csv.splitlines()
    if len(linhas) < 2:
        return []
    cabecalho = linhas[0].split(',')
    try:
        indice_nome = cabecalho.index(coluna_nome)
        indice_nota = cabecalho.index(coluna_nota)
    except ValueError:
        return []
    dados = {}
    for linha in linhas[1:]:
        if not linha:
            continue
        campos = linha.split(',')
        if len(campos) <= max(indice_nome, indice_nota):
            continue
        nome = campos[indice_nome]
        try:
            nota = float(campos[indice_nota])
        except ValueError:
            continue
        if nome not in dados:
            dados[nome] = []
        dados[nome].append(nota)
    resultado = []
    for nome in sorted(dados):
        notas = dados[nome]
        media = sum(notas) / len(notas)
        media_arred = round(media, 2)
        resultado.append((nome, media_arred))
    return resultado

