def find_anagrams(s: str, p: str) -> list[int]:
    if len(p) > len(s) or not p:
        return []
    from collections import Counter
    alvo = Counter(p)
    janela = Counter()
    resultado = []
    tam = len(p)
    for i, char in enumerate(s):
        janela[char] += 1
        if i >= tam:
            if janela[s[i - tam]] == 1:
                del janela[s[i - tam]]
            else:
                janela[s[i - tam]] -= 1
        if janela == alvo:
            resultado.append(i - tam + 1)
    return resultado

def max_area_container(alturas: list[int]) -> int:
