        return 0
    esq, dir = 0, len(alturas) - 1
    max_area = 0
    while esq < dir:
        area = (dir - esq) * min(alturas[esq], alturas[dir])
        max_area = max(max_area, area)
        if alturas[esq] < alturas[dir]:
            esq += 1
        else:
            dir -= 1
    return max_area

def search_rotated(nums: list[int], alvo: int) -> int:
    if not nums:
        return -1
    esq, dir = 0, len(nums) - 1
    while esq <= dir:
        meio = (esq + dir) // 2
        if nums[meio] == alvo:
            return meio
        if nums[esq] <= nums[meio]:  # metade esquerda ordenada
            if nums[esq] <= alvo < nums[meio]:
                dir = meio - 1
            else:
                esq = meio + 1
        else:  # metade direita ordenada
            if nums[meio] < alvo <= nums[dir]:
                esq = meio + 1
            else:
                dir = meio - 1
    return -1

def longest_substring_k_repeating(s: str, k: int) -> int:
