def conta_fins_de_semana(ano: int, mes: int) -> dict:
    """Conta quantos sábados e quantos domingos existem em um mês de um ano.
    Retorna um dicionário com chaves 'sabados' e 'domingos'.
    Se mês for inválido (1-12), retorna um dicionário vazio {}.
    Exemplo: conta_fins_de_semana(2024, 1) -> {'sabados': 4, 'domingos': 4}
    """

solution:
def conta_fins_de_semana(ano: int, mes: int) -> dict:
    from datetime import date, timedelta
    if mes < 1 or mes > 12:
        return {}
    if mes == 12:
        ultimo_dia = date(ano, 12, 31)
    else:
        ultimo_dia = date(ano, mes + 1, 1) - timedelta(days=1)
    primeiro_dia = date(ano, mes, 1)
    sabados = 0
    domingos = 0
    dia = primeiro_dia
    while dia <= ultimo_dia:
        if dia.weekday() == 5:
            sabados += 1
        elif dia.weekday() == 6:
            domingos += 1
        dia += timedelta(days=1)
    return {'sabados': sabados, 'domingos': domingos}

