    if not match:
        return {}
    letras, digito_meio, letra_meio, digitos_finais = match.groups()
    return {
        'letras': letras,
        'digito_meio': int(digito_meio),
        'letra_meio': letra_meio,
        'digitos_finais': int(digitos_finais)
