def maximo_subarray_memo(nums: list) -> int:
    if not nums:
        return 0
    n = len(nums)
    memo = [0] * n
    memo[0] = nums[0]
    for i in range(1, n):
        memo[i] = max(nums[i], memo[i-1] + nums[i])
    return max(memo)

def contar_pulos_memo(n: int) -> int:
    if n <= 0:
        return 0
    memo = [0] * (n + 1)
    memo[0] = 1
    memo[1] = 1
    for i in range(2, n + 1):
        memo[i] = memo[i-1] + memo[i-2]
    return memo[n]

def subsequencia_comum_maxima_pacifico(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def particao_soma_igual_memo(nums: list) -> bool:
    if not nums:
        return False
    total = sum(nums)
    if total % 2 != 0:
        return False
    alvo = total // 2
    dp = [False] * (alvo + 1)
    dp[0] = True
    for num in nums:
        for s in range(alvo, num - 1, -1):
            if dp[s - num]:
                dp[s] = True
    return dp[alvo]

def moda_todas(numeros: list) -> list:
    if not numeros:
        return []
    freq = {}
    for n in numeros:
        freq[n] = freq.get(n, 0) + 1
    max_freq = max(freq.values())
    modas = [k for k, v in freq.items() if v == max_freq]
    return sorted(modas)

def combinacoes_mochila_recursiva(pesos: list[int], capacidade: int) -> int:
    if capacidade < 0:
        return 0
    if not pesos:
        return 1 if capacidade == 0 else 0
    n = len(pesos)
    memo = [[None] * (capacidade + 1) for _ in range(n)]
    def dfs(i, resto):
        if resto == 0:
            return 1
        if i >= n or resto < 0:
            return 0
        if memo[i][resto] is not None:
            return memo[i][resto]
        incluir = dfs(i + 1, resto - pesos[i])
        excluir = dfs(i + 1, resto)
        memo[i][resto] = incluir + excluir
        return memo[i][resto]
    return dfs(0, capacidade)

def maior_substring_palindroma_recursiva(s: str) -> str:
    if not s:
        return ""
    n = len(s)
    memo = {}
    def is_pal(i, j):
        if i >= j:
            return True
        if (i, j) in memo:
            return memo[(i, j)]
        if s[i] == s[j] and is_pal(i+1, j-1):
            memo[(i, j)] = True
            return True
        memo[(i, j)] = False
        return False
    inicio, fim = 0, 0
    for i in range(n):
        for j in range(i, n):
            if is_pal(i, j) and (j - i) > (fim - inicio):
                inicio, fim = i, j
    return s[inicio:fim+1]

def contagem_formas_soma_recursiva(n: int, numeros: list[int]) -> int:
    if n < 0:
        return 0
    if n == 0:
        return 1
    if not numeros:
        return 0
    memo = {}
    def contar(resto):
        if resto == 0:
            return 1
        if resto < 0:
            return 0
        if resto in memo:
            return memo[resto]
        total = 0
        for num in numeros:
            total += contar(resto - num)
        memo[resto] = total
        return total
    return contar(n)

