def intersecao_multiset_com_limite(lista1: list, lista2: list, max_repeticoes: int) -> list:
    from collections import Counter
    contagem2 = Counter(lista2)
    resultado = []
    contagem_restante = {}
    for elemento in lista1:
        if elemento in contagem2:
            if elemento not in contagem_restante:
                contagem_restante[elemento] = min(contagem2[elemento], max_repeticoes)
            if contagem_restante[elemento] > 0:
                resultado.append(elemento)
                contagem_restante[elemento] -= 1
    return resultado

