def fib_memo(n: int) -> int:
    if n < 0:
        return -1
    memo = {0: 0, 1: 1}
    def fib(x):
        if x in memo:
            return memo[x]
        memo[x] = fib(x-1) + fib(x-2)
        return memo[x]
    return fib(n)

def climb_stairs(n: int) -> int:
    if n < 0:
        return 0
    if n <= 1:
        return 1
    memo = {0: 1, 1: 1}
    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k-1) + helper(k-2)
        return memo[k]
    return helper(n)

def min_coins(coins: list[int], amount: int) -> int:
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    memo = {0: 0}
    def helper(rem):
        if rem in memo:
            return memo[rem]
        if rem < 0:
            return -1
        best = float('inf')
        for c in coins:
            res = helper(rem - c)
            if res != -1:
                best = min(best, 1 + res)
        memo[rem] = -1 if best == float('inf') else best
        return memo[rem]
    return helper(amount)

def subset_sum_exists(nums: list[int], target: int) -> bool:
    if target == 0:
        return True
    if not nums:
        return False
    memo = {}
    def helper(i, t):
        if t == 0:
            return True
        if i == len(nums) or t < 0:
            return False
        key = (i, t)
        if key in memo:
            return memo[key]
        memo[key] = helper(i+1, t - nums[i]) or helper(i+1, t)
        return memo[key]
    return helper(0, target)

def partition_equal_sum(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2 != 0:
        return False
    target = total // 2
    if target == 0:
        return True
    memo = {}
    def helper(i, t):
        if t == 0:
            return True
        if i == len(nums) or t < 0:
            return False
        key = (i, t)
        if key in memo:
            return memo[key]
        memo[key] = helper(i+1, t - nums[i]) or helper(i+1, t)
        return memo[key]
    return helper(0, target)

def encontrar_palindromo_mais_longo(texto: str) -> str:
    if not texto:
        return ''
    n = len(texto)
    inicio, max_len = 0, 1
    for i in range(n):
        # ímpar
        l, r = i - 1, i + 1
        while l >= 0 and r < n and texto[l] == texto[r]:
            if r - l + 1 > max_len:
                inicio, max_len = l, r - l + 1
            l -= 1
            r += 1
        # par
        l, r = i, i + 1
        while l >= 0 and r < n and texto[l] == texto[r]:
            if r - l + 1 > max_len:
                inicio, max_len = l, r - l + 1
            l -= 1
            r += 1
    return texto[inicio:inicio + max_len]

