def extrair_numero_telefone(texto: str) -> str | None:
    import re
    padrao = r'\(?(\d{2})\)?\s*(\d{4,5})-?(\d{4})'
    match = re.search(padrao, texto)
    if not match:
        return None
    ddd = match.group(1)
    parte1 = match.group(2)
    parte2 = match.group(3)
    if len(parte1) == 5:
        return f'({ddd}) {parte1}-{parte2}'
    else:
        return f'({ddd}) {parte1}-{parte2}'

