def primos_gemeos_intervalo(inicio: int, fim: int) -> list[tuple[int, int]]:
    if inicio > fim:
        return []

    def eh_primo(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    primos = [i for i in range(inicio, fim + 1) if eh_primo(i)]

    resultado = []
    for i in range(len(primos) - 1):
        if primos[i+1] - primos[i] == 2:
            resultado.append((primos[i], primos[i+1]))
    return resultado

def divisores_proprios_ordenados(n: int) -> list[int]:
    if n <= 1:
        return []

    divisores = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i != n:
                divisores.add(i)
            outro = n // i
            if outro != n:
                divisores.add(outro)
    return sorted(divisores)

def contar_numeros_perfeitos_intervalo(inicio: int, fim: int) -> int:
    if inicio > fim:
        return 0

    def soma_divisores_proprios(n):
        if n <= 1:
            return 0
        soma = 1  # 1 é divisor próprio para n > 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                soma += i
                outro = n // i
                if outro != i and outro != n:
                    soma += outro
        return soma

    count = 0
    for num in range(max(1, inicio), fim + 1):
        if soma_divisores_proprios(num) == num:
            count += 1
    return count

