def amplitude_interquartilica(numeros: list) -> float:
    if len(numeros) < 2:
        return 0.0
    ordenados = sorted(numeros)
    n = len(ordenados)
    # mediana helper
    def mediana(lista):
        m = len(lista)
        if m % 2 == 1:
            return float(lista[m // 2])
        else:
            return (lista[m // 2 - 1] + lista[m // 2]) / 2.0
    if n % 2 == 1:
        # incluindo mediana em ambas as metades
        metade_inferior = ordenados[:n // 2 + 1]
        metade_superior = ordenados[n // 2:]
    else:
        metade_inferior = ordenados[:n // 2]
        metade_superior = ordenados[n // 2:]
    q1 = mediana(metade_inferior)
    q3 = mediana(metade_superior)
    return q3 - q1

def bytes_legiveis(num_bytes: int) -> str:
    if num_bytes == 0:
        return '0 bytes'
    if num_bytes == 1:
        return '1 byte'
    unidades = ['bytes', 'KB', 'MB', 'GB', 'TB', 'PB']
    i = 0
    while num_bytes >= 1024 and i < len(unidades) - 1:
        num_bytes /= 1024.0
        i += 1
    if i == 0:
        return f'{int(num_bytes)} byte{"s" if num_bytes > 1 else ""}'
    import math
    # arredondamento bancário para 1 casa decimal
    valor = num_bytes
    parte_int = int(valor * 10)
    resto = valor * 10 - parte_int
    if abs(resto - 0.5) < 1e-9:
        if parte_int % 2 == 0:
            arred = parte_int / 10.0
        else:
            arred = (parte_int + 1) / 10.0
