def algarismos_em_base(n: int, base: int) -> list[int]:
    if n == 0:
        return [0]
    n = abs(n)
    algs = []
    while n > 0:
        algs.append(n % base)
        n //= base
    algs.reverse()
    return algs

def e_primo_sophie_germain(n: int) -> bool:
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return False
        return True
    if n < 2:
        return False
    return is_prime(n) and is_prime(2 * n + 1)

