import string

def codificar_cesar_especifico(texto: str, chave: int) -> str:
    chave = chave % 26
    resultado = []
    for char in texto:
        if 'A' <= char <= 'Z':
            deslocado = chr((ord(char) - ord('A') + chave) % 26 + ord('A'))
            resultado.append(deslocado)
        elif 'a' <= char <= 'z':
            deslocado = chr((ord(char) - ord('a') + chave) % 26 + ord('a'))
            resultado.append(deslocado)
        else:
            resultado.append(char)
    return ''.join(resultado)

