def agrupar_por_chave_ordem(itens: list[dict], chave: str) -> list[tuple]:
    ordem = []
    grupos = {}
    for item in itens:
        valor = item[chave]
        if valor not in grupos:
            grupos[valor] = []
            ordem.append(valor)
        grupos[valor].append(item)
    return [(v, grupos[v]) for v in ordem]

def filtrar_ordenar_por_ocorrencia(lista: list[int], limite: int) -> list[int]:
    from collections import Counter
    contagem = Counter(lista)
    filtrados = {num: freq for num, freq in contagem.items() if freq >= limite}
    return sorted(filtrados.keys(), key=lambda x: (-filtrados[x], x))

