def ultima_quinta_feira(data: str) -> str:
    from datetime import datetime, timedelta
    dt = datetime.strptime(data, '%d/%m/%Y')
    dias_para_voltar = (dt.weekday() - 3) % 7
    ultima = dt - timedelta(days=dias_para_voltar)
    return ultima.strftime('%d/%m/%Y')

def converte_fuso_horario(data_hora: str, fuso_origem: int, fuso_destino: int) -> str:
    from datetime import datetime, timedelta
    dt = datetime.strptime(data_hora, '%d/%m/%Y %H:%M')
    diferenca = fuso_destino - fuso_origem
    dt_convertida = dt + timedelta(hours=diferenca)
    return dt_convertida.strftime('%d/%m/%Y %H:%M')

