def mediana_ponderada(valores: list, pesos: list) -> float:
    if not valores or not pesos:
        return 0.0
    pares = sorted(zip(valores, pesos))
    total_peso = sum(pesos)
    acum = 0
    for val, peso in pares:
        acum += peso
        if acum >= total_peso / 2:
            return float(val)
    return 0.0

def media_geometrica_ponderada(valores: list, pesos: list) -> float:
    if not valores or not pesos:
        return 0.0
    if any(v < 0 for v in valores):
        return None
    soma_pesos = sum(pesos)
    produto = 1.0
    for v, p in zip(valores, pesos):
        produto *= v ** p
    return round(produto ** (1.0 / soma_pesos), 4)

