    Exemplo:
    >>> contar_frequencia_unicode('aáa')
    {'a': 2, 'á': 1}
    """

solution:
def contar_frequencia_unicode(texto: str) -> dict[str, int]:
    freq = {}
    for char in texto:
        if char == ' ':
            continue
        freq[char] = freq.get(char, 0) + 1
    return freq

