def is_balanced_brackets(s: str) -> bool:
    '''Verifica se os parênteses, colchetes e chaves na string estão balanceados. Considera apenas '()', '[]', '{}'. Strings vazias retornam True.
    Exemplo: is_balanced_brackets('([])') -> True, is_balanced_brackets('([)]') -> False.'''

solution:
def is_balanced_brackets(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in mapping.values():
            stack.append(ch)
        elif ch in mapping:
            if not stack or stack.pop() != mapping[ch]:
                return False
    return not stack

