def longest_common_prefix(strs: list) -> str:
    '''Retorna o prefixo comum mais longo entre todas as strings da lista. Se a lista for vazia, retorna string vazia. Se houver strings vazias, o prefixo é vazio.
    Exemplo: longest_common_prefix(['flower','flow','flight']) -> 'fl'.'''

solution:
def longest_common_prefix(strs: list) -> str:
    if not strs:
        return ''
    for i in range(len(strs[0])):
        char = strs[0][i]
        for s in strs[1:]:
            if i >= len(s) or s[i] != char:
                return strs[0][:i]
    return strs[0]

