def format_name_parts(nome: str) -> str:
    '''Formata um nome completo: cada palavra começa com maiúscula, exceto conectivos (de, da, do, dos, das, e, y, van, von, der, den) que ficam em minúsculo, a menos que sejam a primeira ou última palavra. Espaços extras são removidos. String vazia retorna string vazia.
    Exemplo: format_name_parts('joão da silva') -> 'João da Silva'.'''

solution:
def format_name_parts(nome: str) -> str:
    conectivos = {'de', 'da', 'do', 'dos', 'das', 'e', 'y', 'van', 'von', 'der', 'den'}
    palavras = nome.strip().split()
    resultado = []
    for i, p in enumerate(palavras):
        p = p.lower()
        if i == 0 or i == len(palavras) - 1 or p not in conectivos:
            p = p.capitalize()
        resultado.append(p)
    return ' '.join(resultado)

