def extract_valid_hashtags(tweet: str) -> list:
    '''Extrai hashtags válidas de um texto. Uma hashtag é '#' seguido por uma palavra que começa com letra e contém apenas letras, dígitos e sublinhados. Retorna lista ordenada alfabeticamente (case-insensitive) das hashtags (sem o '#'), mantendo o caso original. Se não houver, retorna lista vazia.
    Exemplo: extract_valid_hashtags('Hoje é #Sextou! #vamos #_test #123') -> ['Sextou', 'vamos'].'''

solution:
def extract_valid_hashtags(tweet: str) -> list:
    import re
    hashtags = re.findall(r'#([A-Za-z][A-Za-z0-9_]*)', tweet)
    return sorted(hashtags, key=str.lower)

