def oxford_comma_join(items: list) -> str:
    '''Concatena uma lista de strings em uma string com vírgulas e 'and', seguindo o estilo Oxford (vírgula antes do 'and' para listas com 3+ itens). Lista vazia retorna ''. Um item retorna o próprio. Dois itens retorna 'item1 and item2'.
    Exemplo: oxford_comma_join(['maçã', 'banana', 'cereja']) -> 'maçã, banana, and cereja'.'''

solution:
def oxford_comma_join(items: list) -> str:
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f'{items[0]} and {items[1]}'
    return ', '.join(items[:-1]) + f', and {items[-1]}'

