solution:
def caminhos_grid_memo(m: int, n: int) -> int:
    from functools import lru_cache
    if m == 0 or n == 0:
        return 0
    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> int:
        if i == 0 or j == 0:
            return 1
        return dp(i-1, j) + dp(i, j-1)
    return dp(m-1, n-1)

def maior_palindromo_subseq(s: str) -> int:
    from functools import lru_cache
    n = len(s)
    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> int:
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 2 + dp(i+1, j-1)
        else:
            return max(dp(i+1, j), dp(i, j-1))
    return dp(0, n-1)

def expressoes_operadores(digitos: str, alvo: int) -> list[str]:
    if not digitos:
        return []
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(idx: int, valor_atual: int, ultimo: int, expr: str) -> list[str]:
        if idx == len(digitos):
            if valor_atual == alvo:
                return [expr]
            return []
        res = []
        # pegar um número, evitando leading zero
        for j in range(idx, len(digitos)):
            if j > idx and digitos[idx] == '0':
                break
            num_str = digitos[idx:j+1]
            num = int(num_str)
            if idx == 0:
                res.extend(dfs(j+1, num, num, num_str))
            else:
                res.extend(dfs(j+1, valor_atual + num, num, expr + '+' + num_str))
                res.extend(dfs(j+1, valor_atual - num, -num, expr + '-' + num_str))
                res.extend(dfs(j+1, valor_atual - ultimo + ultimo * num, ultimo * num, expr + '*' + num_str))
        return res
    return dfs(0, 0, 0, '')

