def soma_total_matriz(matriz: list[list]) -> float:
    total = 0
    for linha in matriz:
        for elem in linha:
            total += elem
    return total

def verificar_simetrica_matriz(matriz: list[list]) -> bool:
    if not matriz:
        return True
    n = len(matriz)
    if n != len(matriz[0]):
        return False
    for i in range(n):
        for j in range(i, n):
            if matriz[i][j] != matriz[j][i]:
                return False
    return True
